857,_binary 'Content translation field settings','','none'),(5858,_binary 'Field properties for which to synchronize translations','','none'),(5859,_binary 'Field column for which to synchronize translations','','none'),(5860,_binary 'Contextual links for an area on a page are displayed using a contextual links button. There are two ways to make the contextual links button visible:','','none'),(5861,_binary 'Once the contextual links button for the area of interest is visible, click the button to display the links.','','none'),(5862,_binary 'The relative date value entered is invalid.','','none'),(5863,_binary 'Add new field: you need to provide a machine name for the field.','','none'),(5864,_binary 'Allowed types: @extensions.','','10.5.6'),(5865,_binary 'Back to content editing','','none'),(5866,_binary '\n        <p>You can align images, videos, blockquotes and so on to the left, right or center. Examples:</p>\n        <ul>\n          <li>Align an image to the left: <code>&lt;img src=\"\" data-align=\"left\" /&gt;</code></li>\n          <li>Align an image to the center: <code>&lt;img src=\"\" data-align=\"center\" /&gt;</code></li>\n          <li>Align an image to the right: <code>&lt;img src=\"\" data-align=\"right\" /&gt;</code></li>\n          <li>… and you can apply this to other elements as well: <code>&lt;video src=\"\" data-align=\"center\" /&gt;</code></li>\n        </ul>','','none'),(5867,_binary 'Align images','','none'),(5868,_binary 'Uses a <code>data-align</code> attribute on <code>&lt;img&gt;</code> tags to align images.','','none'),(5869,_binary '\n        <p>You can caption images, videos, blockquotes, and so on. Examples:</p>\n        <ul>\n            <li><code>&lt;img src=\"\" data-caption=\"This is a caption\" /&gt;</code></li>\n            <li><code>&lt;video src=\"\" data-caption=\"The Drupal Dance\" /&gt;</code></li>\n            <li><code>&lt;blockquote data-caption=\"Dries Buytaert\"&gt;Drupal is awesome!&lt;/blockquote&gt;</code></li>\n            <li><code>&lt;code data-caption=\"Hello world in JavaScript.\"&gt;alert(\"Hello world!\");&lt;/code&gt;</code></li>\n        </ul>','','none'),(5870,_binary 'Caption images','','none'),(5871,_binary 'Uses a <code>data-caption</code> attribute on <code>&lt;img&gt;</code> tags to caption images.','','none'),(5872,_binary 'One translation file could not be imported. See the log for details.@count translation files could not be imported. See the log for details.','','none'),(5873,_binary 'A flag for whether the link should be enabled in menus or hidden.','','10.5.6'),(5874,_binary 'The time that the menu link was last edited.','','none'),(5875,_binary 'The timestamp the latest revision of this node was created.','','none'),(5876,_binary 'Recently created','','none'),(5877,_binary 'Whether a new revision should be created by default','','none'),(5878,_binary 'Display author and date information','','10.5.6'),(5879,_binary 'Breakpoint ID','','none'),(5880,_binary 'Unable to delete the shortcut for %title.','','none'),(5881,_binary 'Drupal database update','','none'),(5882,_binary 'Maximum number of levels','','none'),(5883,_binary '<strong>Back up your code</strong>. Hint: when backing up module code, do not leave that backup in the \'modules\' or \'sites/*/modules\' directories as this may confuse Drupal\'s auto-discovery mechanism.','','none'),(5884,_binary '<strong>Back up your database</strong>. This process will change your database values and in case of emergency you may need to revert to a backup.','','none'),(5885,_binary 'When you have performed the steps above, you may proceed.','','none'),(5886,_binary 'This update will been skipped due to the following missing dependencies:','','none'),(5887,_binary 'This update will be skipped due to an error in the module\'s code.','','none'),(5888,_binary 'The version of Drupal you are updating from has been automatically detected.','','none'),(5889,_binary 'All errors have been logged.','','none'),(5890,_binar