6,_binary 'Translate any configuration including those shipped with modules and themes.','','none'),(6377,_binary 'Time zone override','','none'),(6378,_binary 'Datetime custom display format settings','','none'),(6379,_binary 'Datetime time ago display format settings','','none'),(6380,_binary 'The time zone selected here will always be used','','none'),(6381,_binary 'File URI','Validation','none'),(6382,_binary 'To uninstall Forum, first delete all <em>Forum</em> content','','none'),(6383,_binary 'To uninstall Forum, first delete all %vocabulary terms','','none'),(6384,_binary 'Translate interface text','','10.5.6'),(6385,_binary 'Translate any interface text including configuration shipped with modules and themes.','','10.5.6'),(6386,_binary 'Pages requested by anonymous users are stored the first time they are requested and then are reused. Depending on your site configuration and the amount of your web traffic tied to anonymous visitors, the caching system may significantly increase the speed of your site.','','none'),(6387,_binary 'Configuring the internal page cache','','none'),(6388,_binary 'Internal Page Cache','','none'),(6389,_binary 'Configuring for performance','','none'),(6390,_binary 'Last run: %time ago.','','none'),(6391,_binary 'The path \'%path\' has to start with a slash.','','none'),(6392,_binary 'Allow user to control selected display options for this view.','','10.5.6'),(6393,_binary 'Allow user to control the number of items displayed in this view','','10.5.6'),(6394,_binary 'Allow user to specify number of items skipped from beginning of this view.','','10.5.6'),(6395,_binary 'Testing config import','','none'),(6396,_binary 'Tests install profiles in the config importer.','','none'),(6397,_binary 'Media library','','10.5.6'),(6398,_binary 'Plural variants','','none'),(6399,_binary 'Place block <span class=\"visually-hidden\">in the %region region</span>','','10.5.6'),(6400,_binary 'No blocks available.','','none'),(6401,_binary 'Exporting the full configuration','','none'),(6402,_binary 'Importing a full configuration','','none'),(6403,_binary 'Exporting a single configuration item','','10.5.6'),(6404,_binary 'Importing a single configuration item','','10.5.6'),(6405,_binary 'Configuration synchronization','','10.5.6'),(6406,_binary 'Import and export your configuration.','','10.5.6'),(6407,_binary '@date by @username','','none'),(6408,_binary 'You must include at least one keyword to match in the content, and punctuation is ignored.You must include at least one keyword to match in the content. Keywords must be at least @count characters, and punctuation is ignored.','','none'),(6409,_binary 'Manage responsive image styles.','','none'),(6410,_binary 'This theme is missing a \'content\' region.','','none'),(6411,_binary 'Apache version','','none'),(6412,_binary 'Due to the settings for ServerTokens in httpd.conf, it is impossible to accurately determine the version of Apache running on this server. The reported value is @reported, to run Drupal without mod_rewrite, a minimum version of 2.2.16 is needed.','','none'),(6413,_binary 'Filter by name or description','','10.5.6'),(6414,_binary 'Enter a part of the module name or description','','10.5.6'),(6415,_binary 'Container cannot be saved to cache.','','none'),(6416,_binary 'Drupal could not be correctly setup with the existing database due to the following error: @error.','','none'),(6417,_binary 'The database server version %version is less than the minimum required version %minimum_version.','','none'),(6418,_binary 'A value must be selected for %part.','','none'),(6419,_binary '@title (value @number)','','10.5.6'),(6420,_binary '1 error has been found: @count errors have been found: ','','none'),(6421,_binary 'Shown tabs','','none'),(6422,_binary 'Select tabs being shown in the block','','none'),(6423,_binary 'Show primary tabs','','none'),(6424,_binary 'Show secondary tabs','','none'),(6425,_binary 'The blocked IP address.','','none'),(6426,_binary 'Generating accessible content','','none'),(6427,_binary 'The time that the comment was created, as a Unix timestamp.','','none'),(6428,_binary 'The time that the comment was edited by its author, as a Unix timestamp.','','none'),(6429,_binary 'The module that implements the field type.','','none'),(6430,_binary 'The entity bundle.','','none'),(6431,_binary 'The original machine name of the view mode.','','none'),(6432,_binary 'The view mode ID.','','none'),(6433,_binary 'The name of the format.','','none'),(6434,_binary 'Whether the format is cacheable.','','none'),(6435,_binary 'The role IDs which can use the format.','','none'),(6436,_binary 'The filters configured for the format.','','none'),(6437,_binary 'The status of the format','','none'),(6438,_binary 'The weight of the format','','none'),(6439,_binary 'Weight for @title language detection method','','none'),(6440,_binary 'Enable @title language detection method','','none'),(6441,_binary 'Core (Experimental)','','10.5.6'),(6442,_binary 'Migration @id is busy with another operation: @status','','none'),(6443,_binary '@label (@type)','','none'),(6444,_binary 'Flag indicating the node type is enable','','none'),(6445,_binary 'base node.','','none'),(6446,_binary 'Breakpoint groups: viewport sizing vs art direction','','none'),(6447,_binary 'Breakpoint settings: sizes vs image styles','','none'),(6448,_binary 'Sizes field','','none'),(6449,_binary 'Image styles for sizes','','none'),(6450,_binary 'Failed to load responsive image style: “@style“ while displaying responsive image.','','none'),(6451,_binary 'Viewport Sizing','','none'),(6452,_binary 'Select a breakpoint group from the installed themes and modules. Below you can select which breakpoints to use from this group. You can also select which image style or styles to use for each breakpoint you use.','','none'),(6453,_binary 'Warning: if you change the breakpoint group you lose all your image style selections for each breakpoint.','','none'),(6454,_binary 'Select a breakpoint group from the installed themes and modules.','','none'),(6455,_binary 'Select multiple image styles and use the sizes attribute.','','none'),(6456,_binary 'Select a single image style.','','none'),(6457,_binary 'Do not use this breakpoint.','','none'),(6458,_binary 'Select image styles with widths that range from the smallest amount of space this image will take up in the layout to the largest, bearing in mind that high resolution screens will need images 1.5x to 2x larger.','','none'),(6459,_binary 'Entity/field definitions','','none'),(6460,_binary 'Tabs block','','none'),(6461,_binary 'Whether primary tabs are shown','','none'),(6462,_binary 'Whether secondary tabs are shown','','none'),(6463,_binary 'The existing format/name combination has not been altered.','','none'),(6464,_binary 'Run database updates','','none'),(6465,_binary 'The weight of the role.','','none'),(6466,_binary 'A title semantically associated with your table for increased accessibility.','','none'),(6467,_binary 'Comment_forum','','none'),(6468,_binary 'Default comment field','','none'),(6469,_binary 'Large (480×480)','','10.5.6'),(6470,_binary 'Medium (220×220)','','10.5.6'),(6471,_binary 'Thumbnail (100×100)','','10.5.6'),(6472,_binary 'D, m/d/Y - H:i','PHP date format','10.5.6'),(6473,_binary 'HTML Date','','10.5.6'),(6474,_binary 'HTML Datetime','','10.5.6'),(6475,_binary 'HTML Month','','10.5.6'),(6476,_binary 'HTML Time','','10.5.6'),(6477,_binary 'HTML Week','','10.5.6'),(6478,_binary 'HTML Year','','10.5.6'),(6479,_binary 'HTML Yearless date','','10.5.6'),(6480,_binary 'Default long date','','10.5.6'),(6481,_binary 'l, F j, Y - H:i','PHP date format','10.5.6'),(6482,_binary 'Default medium date','','10.5.6'),(6483,_binary 'Default short date','','10.5.6'),(6484,_binary 'm/d/Y - H:i','PHP date format','10.5.6'),(6485,_binary 'User account menu','','10.5.6'),(6486,_binary 'Block the selected user(s)','','10.5.6'),(6487,_binary 'Cancel the selected user account(s)','','10.5.6'),(6488,_binary 'Unblock the selected user(s)','','10.5.6'),(6489,_binary 'Basic block','','10.5.6'),(6490,_binary 'A basic block contains a title and a body.','','10.5.6'),(6491,_binary 'Website feedback','','10.5.6'),(6492,_binary 'Enter a comma-separated list. For example: Amsterdam, Mexico City, \"Cleveland, Ohio\"','','10.5.6'),(6493,_binary 'Basic HTML','','10.5.6'),(6494,_binary 'Restricted HTML','','10.5.6'),(6495,_binary 'Overridden block the selected user(s)','','none'),(6496,_binary 'The installer requires that you create a translations directory as part of the installation process. Create the directory %translations_directory . More details about installing Drupal are available in <a href=\":install_txt\">INSTALL.txt</a>.','','none'),(6497,_binary 'The installer requires read permissions to %translations_directory at all times. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none'),(6498,_binary 'The installer requires write permissions to %translations_directory during the installation process. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none'),(6499,_binary 'The installer requires to contact the translation server to download a translation file. Check your internet connection and verify that your website can reach the translation server at <a href=\":server_url\">@server_url</a>.','','none'),(6500,_binary 'The %language translation file is not available at the translation server. <a href=\":url\">Choose a different language</a> or select English and translate your website later.','','none'),(6501,_binary 'The %language translation file could not be downloaded. <a href=\":url\">Choose a different language</a> or select English and translate your website later.','','none'),(6502,_binary 'The @drupal installer requires that you create a %file as part of the installation process. Copy the %default_file file to %file. More details about installing Drupal are available in <a href=\":install_txt\">INSTALL.txt</a>.','','none'),(6503,_binary '@drupal requires read permissions to %file at all times. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none'),(6504,_binary 'The @drupal installer requires write permissions to %file during the installation process. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none'),(6505,_binary 'The @drupal installer failed to create a %file file with proper file ownership. Log on to your web server, remove the existing %file file, and create a new one by copying the %default_file file to %file. More details about installing Drupal are available in <a href=\":install_txt\">INSTALL.txt</a>. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none'),(6506,_binary 'Check the messages and <a href=\":retry\">retry</a>, or you may choose to <a href=\":cont\">continue anyway</a>.','','none'),(6507,_binary 'Check the messages and <a href=\":url\">try again</a>.','','none'),(6508,_binary 'The following modules are required but were not found. Move them into the appropriate modules subdirectory, such as <em>/modules</em>. Missing modules: @modules','','none'),(6509,_binary 'Updating @module','','none'),(6510,_binary 'Entity type mismatch on rename. @old_type not equal to @new_type for existing configuration @old_name and staged configuration @new_name.','','none'),(6511,_binary 'Rename operation for simple configuration. Existing configuration @old_name and staged configuration @new_name.','','none'),(6512,_binary 'The %driver database must use %encoding encoding to work with Drupal. Recreate the database with %encoding encoding. See <a href=\"INSTALL.pgsql.txt\">INSTALL.pgsql.txt</a> for more details.','','none'),(6513,_binary 'The %setting setting is currently set to \'%current_value\', but needs to be \'%needed_value\'. Change this by running the following query: <code>@query</code>','','none'),(6514,_binary '@uri','','none'),(6515,_binary 'Operating in maintenance mode. <a href=\":url\">Go online.</a>','','none'),(6516,_binary 'Textfield size: @size','','10.5.6'),(6517,_binary 'Number of rows: @rows','','10.5.6'),(6518,_binary 'URI field size: @size','','none'),(6519,_binary 'WARNING: You are not using an encrypted connection, so your password will be sent in plain text. <a href=\":https-link\">Learn more</a>.','','none'),(6520,_binary '@name cannot be longer than %max characters but is currently %length characters long.','','none'),(6521,_binary '<ul>\n<li>To start over, you must empty your existing database and copy <em>default.settings.php</em> over <em>settings.php</em>.</li>\n<li>To upgrade an existing installation, proceed to the <a href=\":update-url\">update script</a>.</li>\n<li>View your <a href=\":base-url\">existing site</a>.</li>\n</ul>','','none'),(6522,_binary 'All necessary changes to %dir and %file have been made, so you should remove write permissions to them now in order to avoid security risks. If you are unsure how to do so, consult the <a href=\":handbook_url\">online handbook</a>.','','10.5.6'),(6523,_binary 'Unique field constraint','Validation','none'),(6524,_binary 'A @entity_type with @field_name %value already exists.','','none'),(6525,_binary 'The message that should be sent. You may include placeholders like [node:title], [user:account-name], [user:display-name] and [comment:body] to represent data that will be different each time message is sent. Not all placeholders will be available in all contexts.','','none'),(6526,_binary 'The message to be displayed to the current user. You may include placeholders like [node:title], [user:account-name], [user:display-name] and [comment:body] to represent data that will be different each time message is sent. Not all placeholders will be available in all contexts.','','none'),(6527,_binary 'The Ban module allows administrators to ban visits to their site from individual IP addresses. For more information, see the <a href=\":url\">online documentation for the Ban module</a>.','','none'),(6528,_binary 'Administrators can enter IP addresses to ban on the <a href=\":bans\">IP address bans</a> page.','','none'),(6529,_binary 'The HTTP Basic Authentication module supplies an <a href=\"http://en.wikipedia.org/wiki/Basic_access_authentication\">HTTP Basic authentication</a> provider for web service requests. This authentication provider authenticates requests using the HTTP Basic Authentication username and password, as an alternative to using Drupal\'s standard cookie-based authentication system. It is only useful if your site provides web services configured to use this type of authentication (for instance, the <a href=\":rest_help\">RESTful Web Services module</a>). For more information, see the <a href=\":hba_do\">online documentation for the HTTP Basic Authentication module</a>.','','none'),(6530,_binary 'The Block module allows you to place blocks in regions of your installed themes, and configure block settings. For more information, see the <a href=\":blocks-documentation\">online documentation for the Block module</a>.','','none'),(6531,_binary 'You can see where the regions are for the current theme by clicking the <em>Demonstrate block regions</em> link on the <a href=\":blocks\">Block layout page</a>. Regions are specific to each theme.','','none'),(6532,_binary 'To change the settings of an individual block click on the <em>Configure</em> link on the <a href=\":blocks\">Block layout page</a>. The available options vary depending on the module that provides the block. For all blocks you can change the block title and toggle whether to display it.','','none'),(6533,_binary 'You have not created any block types yet. Go to the <a href=\":url\">block type creation page</a> to add a new block type.','','none'),(6534,_binary 'You can assign separate permissions for <em>creating new books</em> as well as <em>creating</em>, <em>editing</em> and <em>deleting</em> book content. Users with the <em>Administer book outlines</em> permission can add <em>any</em> type of content to a book by selecting the appropriate book outline while editing the content. They can also view a list of all books, and edit and rearrange section titles on the <a href=\":admin-book\">Book list page</a>.','','none'),(6535,_binary 'Users with the <em>Add content and child pages to books</em> permission will see a link to <em>Add child page</em> when viewing a content item that is part of a book outline. This link will allow users to create a new content item of the content type you select on the <a href=\":admin-settings\">Book settings page</a>. By default this is the <em>Book page</em> content type.','','none'),(6536,_binary 'Book pages have a default book-specific navigation block. This navigation block contains links that lead to the previous and next pages in the book, and to the level above the current page in the book\'s structure. This block can be enabled on the <a href=\':admin-block\'>Blocks layout page</a>. For book pages to show up in the book navigation, they must be added to a book outline.','','none'),(6537,_binary 'The outline feature allows you to include pages in the <a href=\":book\">Book hierarchy</a>, as well as move them within the hierarchy or to <a href=\":book-admin\">reorder an entire book</a>.','','none'),(6538,_binary 'The parent page in the book. The maximum depth for a book and all child pages is @maxdepth. Some pages in the selected book may not be available as parents if selecting them would exceed this limit.','','none'),(6539,_binary 'The Breakpoint module keeps track of the height, width, and resolution breakpoints where a responsive design needs to change in order to respond to different devices being used to view the site. This module does not have a user interface. For more information, see the <a href=\":docs\">online documentation for the Breakpoint module</a>.','','none'),(6540,_binary '<a href=\":w3\">Media  queries</a> are a formal way to encode breakpoints. For instance, a width breakpoint at 40em would be written as the media query \"(min-width: 40em)\". Breakpoints are really just media queries with some additional meta-data, such as a name and multiplier information.','','none'),(6541,_binary 'The Comment module allows users to comment on site content, set commenting defaults and permissions, and moderate comments. For more information, see the <a href=\":comment\">online documentation for the Comment module</a>.','','none'),(6542,_binary 'Enabling commenting','','none'),(6543,_binary 'Configuring commenting settings','','none'),(6544,_binary 'Users with the appropriate permissions can override the default commenting settings of an entity type when they create an item of that type.','','none'),(6545,_binary 'Comments from users who have the <em>Skip comment approval</em> permission are published immediately. All other comments are placed in the <a href=\":comment-approval\">Unapproved comments</a> queue, until a user who has permission to <em>Administer comments and comment settings</em> publishes or deletes them. Published comments can be bulk managed on the <a href=\":admin-comment\">Published comments</a> administration page. When a comment has no replies, it remains editable by its author, as long as the author has <em>Edit own comments</em> permission.','','none'),(6546,_binary 'In reply to @parent_title by @parent_username','','none'),(6547,_binary 'Name for @anonymous','','none'),(6548,_binary '<a href=\":login\">Log in</a> or <a href=\":register\">register</a> to post comments','','none'),(6549,_binary '<a href=\":login\">Log in</a> to post comments','','none'),(6550,_binary 'Select the Comment type to use for this comment field. Manage the comment types from the <a href=\":url\">administration overview page</a>.','','none'),(6551,_binary 'The Configuration Manager module provides a user interface for importing and exporting configuration changes between installations of your website in different environments. Configuration is stored in YAML format. For more information, see the <a href=\":url\">online documentation for the Configuration Manager module</a>.','','none'),(6552,_binary 'You can create and download an archive consisting of all your site\'s configuration exported as <em>*.yml</em> files on the <a href=\":url\">Export</a> page.','','none'),(6553,_binary 'You can upload a full site configuration from an archive file on the <a href=\":url\">Import</a> page. When importing data from a different environment, the site and import files must have matching configuration values for UUID in the <em>system.site</em> configuration item. That means that your other environments should initially be set up as clones of the target site. Migrations are not supported.','','none'),(6554,_binary 'You can review differences between the active configuration and an imported configuration archive on the <a href=\":synchronize\">Synchronize</a> page to ensure that the changes are as expected, before finalizing the import. The Synchronize page also shows configuration items that would be added or removed.','','none'),(6555,_binary 'You can export a single configuration item by selecting a <em>Configuration type</em> and <em>Configuration name</em> on the <a href=\":single-export\">Single export</a> page. The configuration and its corresponding <em>*.yml file name</em> are then displayed on the page for you to copy.','','none'),(6556,_binary 'You can import a single configuration item by pasting it in YAML format into the form on the <a href=\":single-import\">Single import</a> page.','','none'),(6557,_binary 'Export and download the full configuration of this site as a gzipped tar file.','','none'),(6558,_binary 'Choose a configuration item to display its YAML structure.','','none'),(6559,_binary 'Import a single configuration item by pasting its YAML structure into the text field.','','none'),(6560,_binary 'Full archive','','none'),(6561,_binary 'Single item','','10.5.6'),(6562,_binary 'Staged','','none'),(6563,_binary 'The following items in your active configuration have changes since the last import that may be lost on the next import.','','none'),(6564,_binary '@collection configuration collection','','none'),(6565,_binary '@source_name to @target_name','','none'),(6566,_binary 'The Configuration Translation module allows you to translate configuration text; for example, the site name, vocabularies, menus, or date formats. Together with the modules <a href=\":language\">Language</a>, <a href=\":content-translation\">Content Translation</a>, and <a href=\":locale\">Interface Translation</a>, it allows you to build multilingual websites. For more information, see the <a href=\":doc_url\">online documentation for the Configuration Translation module</a>.','','none'),(6567,_binary 'In order to translate configuration, the website must have at least two <a href=\":url\">languages</a>.','','none'),(6568,_binary 'Users with the <em>Translate user edited configuration</em> permission can access the configuration translation overview, and manage translations for specific languages. The <a href=\":translation-page\">Configuration translation</a> page shows a list of all configuration text that can be translated, either as individual items or as lists. After you click on <em>Translate</em>, you are provided with a list of all languages. You can <em>add</em> or <em>edit</em> a translation for a specific language. Users with specific configuration permissions can also <em>edit</em> the text for the site\'s default language. For some configuration text items (for example for the site information), the specific translation pages can also be accessed directly from their configuration pages.','','none'),(6569,_binary 'You can choose to translate date formats on the <a href=\":translation-page\">Configuration translation</a> page. This allows you not only to translate the label text, but also to set a language-specific <em>PHP date format</em>.','','none'),(6570,_binary '@label <span class=\"visually-hidden\">(@source_language)</span>','','none'),(6571,_binary 'The Contact module allows visitors to contact registered users on your site, using the personal contact form, and also allows you to set up site-wide contact forms. For more information, see the <a href=\":contact\">online documentation for the Contact module</a>.','','none'),(6572,_binary 'On the <a href=\":contact_admin\">Contact forms page</a>, you can configure the fields and display of the personal contact form, and you can set up one or more site-wide contact forms. Each site-wide contact form has a machine name, a label, and one or more defined recipients; when a site visitor submits the form, the field values are sent to those recipients.','','none'),(6573,_binary 'One site-wide contact form can be designated as the default contact form. If you choose to designate a default form, the <em>Contact</em> menu link in the <em>Footer</em> menu will link to it. You can modify this link from the <a href=\":menu-settings\">Menus page</a> if you have the Menu UI module installed. You can also create links to other contact forms; the URL for each form you have set up has format <em>contact/machine_name_of_form</em>.','','none'),(6574,_binary 'From the <a href=\":contact_admin\">Contact forms page</a>, you can configure the fields to be shown on contact forms, including their labels and help text. If you would like other content (such as text or images) to appear on a contact form, use a block. You can create and edit blocks on the <a href=\":blocks\">Block layout page</a>, if the Block module is installed.','','none'),(6575,_binary '[@form] @subject','','none'),(6576,_binary '@sender-name (@sender-url) sent a message using the contact form at @form-url.','','none'),(6577,_binary '[@site-name] @subject','','none'),(6578,_binary 'Hello @recipient-name,','','none'),(6579,_binary '@sender-name (@sender-url) has sent you a message via your contact form at @site-name.','','none'),(6580,_binary '@name (not verified)','','none'),(6581,_binary 'The contact form has not been configured. <a href=\":add\">Add one or more forms</a> .','','none'),(6582,_binary 'In order to translate content, the website must have at least two <a href=\":url\">languages</a>. When that is the case, you can enable translation for the desired content entities on the <a href=\":translation-entity\">Content language</a> page. When enabling translation you can choose the default language for content and decide whether to show the language selection field on the content editing forms.','','none'),(6583,_binary 'Before you can translate content, there must be at least two languages added on the <a href=\":url\">languages administration</a> page.','','none'),(6584,_binary 'To configure translation for this field, <a href=\":language-settings-url\">enable language support</a> for this type.','','none'),(6585,_binary '<a href=\":settings_url\">Enable translation</a> for <em>content types</em>, <em>taxonomy vocabularies</em>, <em>accounts</em>, or any other element you wish to translate.','','none'),(6586,_binary 'The Contextual links module gives users with the <em>Use contextual links</em> permission quick access to tasks associated with certain areas of pages on your site. For example, a menu displayed as a block has links to edit the menu and configure the block. For more information, see the <a href=\":contextual\">online documentation for the Contextual Links module</a>.','','none'),(6587,_binary 'Hovering over the area of interest will temporarily make the contextual links button visible (which looks like a pencil in most themes, and is normally displayed in the upper right corner of the area). The icon typically looks like this: @picture','','none'),(6588,_binary 'The Datetime module provides a Date field that stores dates and times. It also provides the Form API elements <em>datetime</em> and <em>datelist</em> for use in programming modules. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI module help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":datetime_do\">online documentation for the Datetime module</a>.','','none'),(6589,_binary 'The <em>settings</em> and the <em>display</em> of the Date field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6590,_binary 'Dates can be displayed using the <em>Plain</em> or the <em>Default</em> formatter. The <em>Plain</em> formatter displays the date in the <a href=\"http://en.wikipedia.org/wiki/ISO_8601\">ISO 8601</a> format. If you choose the <em>Default</em> formatter, you can choose a format from a predefined list that can be managed on the <a href=\":date_format_list\">Date and time formats</a> page.','','none'),(6591,_binary 'Date part order: @order','','none'),(6592,_binary 'Time type: @time_type','','none'),(6593,_binary 'Time increments: @increment','','none'),(6594,_binary 'The Database Logging module logs system events in the Drupal database. For more information, see the <a href=\":dblog\">online documentation for the Database Logging module</a>.','','none'),(6595,_binary 'The Database Logging module allows you to view an event log on the <a href=\":dblog\">Recent log messages</a> page. The log is a chronological list of recorded events containing usage data, performance data, errors, warnings and operational information. Administrators should check the log on a regular basis to ensure their site is working properly.','','none'),(6596,_binary 'In case of errors or problems with the site, the <a href=\":dblog\">Recent log messages</a> page can be useful for debugging, since it shows the sequence of events. The log messages include usage information, warnings, and errors.','','none'),(6597,_binary 'The maximum number of messages to keep in the database log. Requires a <a href=\":cron\">cron maintenance task</a>.','','none'),(6598,_binary 'Pages which are suitable for caching are cached the first time they are requested, then the cached version is served for all later requests. Dynamic content is handled automatically so that both cache correctness and hit ratio is maintained.','','none'),(6599,_binary 'Internal Dynamic Page Cache','','none'),(6600,_binary 'On the <a href=\":formats\">Text formats and editors page</a> you can see which text editor is associated with each text format. You can change this by clicking on the <em>Configure</em> link, and then choosing a text editor or <em>none</em> from the <em>Text editor</em> drop-down list. The text editor will then be displayed with any text field for which this text format is chosen.','','none'),(6601,_binary 'The <em>settings</em> and the <em>display</em> of the entity reference field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6602,_binary 'No eligible views were found. <a href=\":create\">Create a view</a> with an <em>Entity Reference</em> display, or add such a display to an <a href=\":existing\">existing view</a>.','','none'),(6603,_binary 'The Field module allows custom data fields to be defined for <em>entity</em> types (see below). The Field module takes care of storing, loading, editing, and rendering field data. Most users will not interact with the Field module directly, but will instead use the <a href=\":field-ui-help\">Field UI module</a> user interface. Module developers can use the Field API to make new entity types \"fieldable\" and thus allow fields to be attached to them. For more information, see the <a href=\":field\">online documentation for the Field module</a>.','','none'),(6604,_binary 'You can add, edit, and delete view modes for entities on the <a href=\":view_modes\">View modes page</a>, and you can add, edit, and delete form modes for entities on the <a href=\":form_modes\">Form modes page</a>. Once you have defined a view mode or form mode for an entity type, it will be available on the Manage display or Manage form display page for each sub-type of that entity.','','none'),(6605,_binary 'There are no fields yet added. You can add new fields on the <a href=\":link\">Manage fields</a> page.','','none'),(6606,_binary 'The %display_mode mode now uses custom display settings. You might want to <a href=\":url\">configure them</a>.','','10.5.6'),(6607,_binary '@size limit.','','10.5.6'),(6608,_binary 'file from @field_name','','none'),(6609,_binary 'The File module allows you to create fields that contain files. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":file_documentation\">online documentation for the File module</a>.','','none'),(6610,_binary 'The <em>settings</em> and the <em>display</em> of the file field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6611,_binary 'Uploaded files can either be stored as <em>public</em> or <em>private</em>, depending on the <a href=\":file-system\">File system settings</a>. For more information, see the <a href=\":system-help\">System module help page</a>.','','none'),(6612,_binary 'The file used in the @name field may not be referenced.','','none'),(6613,_binary 'The file referenced by the @name field does not exist.','','none'),(6614,_binary 'Use the <a href=\":url\">@label</a> text format','','10.5.6'),(6615,_binary 'If you do encounter problems, try using HTML character entities. A common example looks like &amp;amp; for an ampersand &amp; character. For a full list of entities see HTML\'s <a href=\":html-entities\">entities</a> page. Some of the available characters include:','','none'),(6616,_binary 'Limit allowed HTML tags and correct faulty HTML','','10.5.6'),(6617,_binary 'The Forum module adds and uses a content type called <em>Forum topic</em>. For background information on content types, see the <a href=\":node_help\">Node module help page</a>.','','none'),(6618,_binary 'For more information, see the <a href=\":forum\">online documentation for the Forum module</a>.','','none'),(6619,_binary 'Visit the <a href=\":forums\">Forums page</a> to set up containers and forums to hold your discussion topics.','','none'),(6620,_binary 'The <a href=\":create-topic\">Forum topic</a> link on the <a href=\":content-add\">Add content</a> page creates the first post of a new threaded discussion, or thread.','','none'),(6621,_binary 'To uninstall Forum, first delete all <a href=\":url\">%vocabulary</a> terms','','none'),(6622,_binary 'No containers or forums available. <a href=\":container\">Add container</a> or <a href=\":forum\">Add forum</a>.','','none'),(6623,_binary '<strong>Configure your website</strong> Once logged in, visit the <a href=\":admin\">Administration page</a>, where you may <a href=\":config\">customize and configure</a> all aspects of your website.','','none'),(6624,_binary '<strong>Customize your website design</strong> To change the \"look and feel\" of your website, visit the <a href=\":themes\">Appearance page</a>. You may choose from one of the included themes or download additional themes from the <a href=\":download_themes\">Drupal.org themes page</a>.','','none'),(6625,_binary '<strong>Start posting content</strong> Finally, you may <a href=\":content\">add new content</a> to your website.','','none'),(6626,_binary 'The Help module displays explanations for using each module listed on the main <a href=\":help\">Help reference page</a>.','','none'),(6627,_binary 'Page-specific help text provided by modules is displayed in the Help block. This block can be placed and configured on the <a href=\":blocks\">Block layout page</a>.','','none'),(6628,_binary 'The History module keeps track of which content a user has read. It marks content as <em>new</em> or <em>updated</em> depending on the last time the user viewed it. History records that are older than one month are removed during cron, which means that content older than one month is always considered <em>read</em>. The History module does not have a user interface but it provides a filter to <a href=\":views-help\">Views</a> to show new or updated content. For more information, see the <a href=\":url\">online documentation for the History module</a>.','','none'),(6629,_binary 'image from @field_name','','none'),(6630,_binary 'The Image module allows you to create fields that contain image files and to configure <a href=\":image_styles\">Image styles</a> that can be used to manipulate the display of images. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for terminology and general information on entities, fields, and how to create and manage fields. For more information, see the <a href=\":image_documentation\">online documentation for the Image module</a>.','','none'),(6631,_binary 'The concept of image styles is that you can upload a single image but display it in several ways; each display variation, or <em>image style</em>, is the result of applying one or more <em>effects</em> to the original image. As an example, you might upload a high-resolution image with a 4:3 aspect ratio, and display it scaled down, square cropped, or black-and-white (or any combination of these effects). The Image module provides a way to do this efficiently: you configure an image style with the desired effects on the <a href=\":image\">Image styles page</a>, and the first time a particular image is requested in that style, the effects are applied. The resulting image is saved, and the next time that same style is requested, the saved image is retrieved without the need to recalculate the effects. Drupal core provides several effects that you can use to define styles; others may be provided by contributed modules.','','none'),(6632,_binary 'When you create an image field, you will need to choose whether the uploaded images will be stored in the public or private file directory defined in your settings.php file and shown on the <a href=\":file-system\">File system page</a>. This choice cannot be changed later. You can also configure your field to store files in a subdirectory of the public or private directory; this setting can be changed later and can be different for each entity sub-type using the field. For more information on file storage, see the <a href=\":system-help\">System module help page</a>.','','none'),(6633,_binary 'There are currently no styles. <a href=\":url\">Add a new one</a>.','','none'),(6634,_binary 'Both a height and width value must be specified in the @name field.','','none'),(6635,_binary 'The primary identifier for an image style.','','none'),(6636,_binary 'The style machine name.','','none'),(6637,_binary 'The style administrative name.','','none'),(6638,_binary 'By default, content is created in the site\'s default language and no language selector is displayed on content creation pages. On the <a href=\":content_language\">Content language</a> page you can customize the language configuration for any supported content entity on your site (for example for content types or menu links). After choosing an entity, you are provided with a drop-down menu to set the default language and a check-box to display language selectors.','','none'),(6639,_binary 'The <a href=\":detection\">Detection and selection</a> page provides several methods for deciding which language is used for displaying interface text. When a method detects and selects an interface language, then the following methods in the list are not applied. You can order them by importance, with your preferred method at the top of the list, followed by one or several fall-back methods.','','none'),(6640,_binary '<em>Browser</em> sets the interface language based on the browser\'s language settings. Since browsers use different language codes to refer to the same languages, you can add and edit languages codes to map the browser language codes to the <a href=\":language_list\">language codes</a> used on your site.','','none'),(6641,_binary 'Reorder the configured languages to set their order in the language switcher block and, when editing content, in the list of selectable languages. This ordering does not impact <a href=\":detection\">detection and selection</a>.','','10.5.6'),(6642,_binary 'The site default language can also be set. It is not recommended to change the default language on a working site. <a href=\":language-detection\">Configure the Selected language</a> setting on the detection and selection page to change the fallback language for language selection.','','10.5.6'),(6643,_binary 'Define how to decide which language is used to display page elements (primarily text provided by modules, such as field labels and help text). This decision is made by evaluating a series of detection methods for languages; the first detection method that gets a result will determine which language is used for that type of text. Be aware that some language detection methods are unreliable under certain conditions, such as browser detection when page-caching is enabled and a user is not currently logged in. Define the order of evaluation of language detection methods on this page. The default language can be changed in the <a href=\":admin-change-language\">list of languages</a>.','','none'),(6644,_binary 'Browsers use different language codes to refer to the same languages. Internally, a best effort is made to determine the correct language based on the code that the browser sends. You can add and edit additional mappings from browser language codes to <a href=\":configure-languages\">site languages</a>.','','none'),(6645,_binary 'Changing the selected language here (and leaving this option as the last among the detection and selection options) is the easiest way to change the fallback language for the website, if you need to change how your site works by default (e.g., when using an empty path prefix or using the default domain). <a href=\":admin-change-language\">Changing the site\'s default language</a> itself might have other undesired side effects.','','none'),(6646,_binary 'Explanation of the language options is found on the <a href=\":languages_list_page\">languages list page</a>.','','10.5.6'),(6647,_binary 'Site\'s default language (@language)','','10.5.6'),(6648,_binary 'Use one of the language switcher blocks to allow site visitors to switch between languages. You can enable these blocks on the <a href=\":block-admin\">block administration page</a>.','','none'),(6649,_binary 'Use language codes as <a href=\":w3ctags\">defined by the W3C</a> for interoperability. <em>Examples: \"en\", \"en-gb\" and \"zh-hant\".</em>','','none'),(6650,_binary '%field must be a valid language tag as <a href=\":url\">defined by the W3C</a>.','','none'),(6651,_binary 'The prefix may only be left blank for the <a href=\":url\">selected detection fallback language.</a>','','none'),(6652,_binary 'The Link module allows you to create fields that contain internal or external URLs and optional link text. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":link_documentation\">online documentation for the Link module</a>.','','none'),(6653,_binary 'The <em>settings</em> and the <em>display</em> of the link field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6654,_binary 'One translation file could not be checked. <a href=\":url\">See the log</a> for details.@count translation files could not be checked. <a href=\":url\">See the log</a> for details.','','none'),(6655,_binary 'One translation file could not be imported. <a href=\":url\">See the log</a> for details.@count translation files could not be imported. <a href=\":url\">See the log</a> for details.','','none'),(6656,_binary 'One translation string was skipped because of disallowed or malformed HTML. <a href=\":url\">See the log</a> for details.@count translation strings were skipped because of disallowed or malformed HTML. <a href=\":url\">See the log</a> for details.','','none'),(6657,_binary 'The Interface Translation module allows you to translate interface text (<em>strings</em>) into different languages, and to switch between them for the display of interface text. It uses the functionality provided by the <a href=\":language\">Language module</a>. For more information, see the <a href=\":doc-url\">online documentation for the Interface Translation module</a>.','','none'),(6658,_binary 'You can check how much of the interface on your site is translated into which language on the <a href=\":languages\">Languages</a> page. On the <a href=\":translation-updates\">Available translation updates</a> page, you can check whether interface translation updates are available on the <a href=\":server\">Drupal translation server</a>.','','none'),(6659,_binary 'You can translate individual strings directly on the <a href=\":translate\">User interface translation</a> page, or download the currently-used translation file for a specific language on the <a href=\":export\">Interface translation export</a> page. Once you have edited the translation file, you can then import it again on the <a href=\":import\">Interface translation import</a> page.','','none'),(6660,_binary 'This page allows a translator to search for specific translated and untranslated strings, and is used when creating or editing translations. (Note: Because translation tasks involve many strings, it may be more convenient to <a title=\"User interface translation export\" href=\":export\">export</a> strings for offline editing in a desktop Gettext translation editor.) Searches may be limited to strings in a specific language.','','10.5.6'),(6661,_binary 'This page allows translators to manually import translated strings contained in a Gettext Portable Object (.po) file. Manual import may be used for customized translations or for the translation of custom modules and themes. To customize translations you can download a translation file from the <a href=\":url\">Drupal translation server</a> or <a title=\"User interface translation export\" href=\":export\">export</a> translations from the site, customize the translations using a Gettext translation editor, and import the result using this page.','','none'),(6662,_binary 'Updates available for: @languages. See the <a href=\":updates\">Available translation updates</a> page for more information.','','none'),(6663,_binary 'Missing translations for: @languages. See the <a href=\":updates\">Available translation updates</a> page for more information.','','none'),(6664,_binary 'No translation status is available. See the <a href=\":updates\">Available translation updates</a> page for more information.','','none'),(6665,_binary 'Interface translation settings','','none'),(6666,_binary 'Interface translation import','','none'),(6667,_binary 'Interface translation export','','none'),(6668,_binary 'Select how frequently you want to check for new interface translations for your currently installed modules and themes. <a href=\":url\">Check updates now</a>.','','none'),(6669,_binary 'Translation files are stored locally in the  %path directory. You can change this directory on the <a href=\":url\">File system</a> configuration page.','','none'),(6670,_binary 'Translation files will not be stored locally. Change the Interface translation directory on the <a href=\":url\">File system configuration</a> page.','','none'),(6671,_binary 'You have selected local translation source, but no <a href=\":url\">Interface translation directory</a> was configured.','','none'),(6672,_binary 'No translatable languages available. <a href=\":add_language\">Add a language</a> first.','','none'),(6673,_binary 'No translation status available. <a href=\":check\">Check manually</a>.','','none'),(6674,_binary 'It is required by the Menu UI module, which provides an interface for managing menus and menu links. For more information, see the <a href=\":menu-help\">Menu UI module help page</a> and the <a href=\":drupal-org-help\">online documentation for the Custom Menu Links module</a>.','','none'),(6675,_binary 'The Menu UI module provides an interface for managing menus. A menu is a hierarchical collection of links, which can be within or external to the site, generally used for navigation. For more information, see the <a href=\":menu\">online documentation for the Menu UI module</a>.','','none'),(6676,_binary 'You can enable the newly-created block for this menu on the <a href=\":blocks\">Block layout page</a>.','','10.5.6'),(6677,_binary 'Each menu has a corresponding block that is managed on the <a href=\":blocks\">Block layout page</a>.','','10.5.6'),(6678,_binary 'There are no menu links yet. <a href=\":url\">Add link</a>.','','10.5.6'),(6679,_binary 'The Migrate module provides a framework for migrating data, usually from an external source into your site. It does not provide a user interface. For more information, see the <a href=\":migrate\">online documentation for the Migrate module</a>.','','none'),(6680,_binary 'Memory usage is @usage (@pct% of limit @limit), reclaiming memory.','','none'),(6681,_binary 'Memory usage is now @usage (@pct% of limit @limit), not enough reclaimed, starting new batch','','none'),(6682,_binary 'Memory usage is now @usage (@pct% of limit @limit), reclaimed enough, continuing','','none'),(6683,_binary 'The Migrate Drupal module provides a framework based on the <a href=\":migrate\">Migrate module</a> to facilitate migration from a Drupal (6, 7, or 8) site to your website. It does not provide a user interface. For more information, see the <a href=\":migrate_drupal\">online documentation for the Migrate Drupal module</a>.','','none'),(6684,_binary 'The content access permissions need to be rebuilt. <a href=\":node_access_rebuild\">Rebuild permissions</a>.','','none'),(6685,_binary 'The Node module manages the creation, editing, deletion, settings, and display of the main site content. Content items managed by the Node module are typically displayed as pages on your site, and include a title, some meta-data (author, creation time, content type, etc.), and optional fields containing text or other data (fields are managed by the <a href=\":field\">Field module</a>). For more information, see the <a href=\":node\">online documentation for the Node module</a>.','','none'),(6686,_binary 'When new content is created, the Node module records basic information about the content, including the author, date of creation, and the <a href=\":content-type\">Content type</a>. It also manages the <em>publishing options</em>, which define whether or not the content is published, promoted to the front page of the site, and/or sticky at the top of content lists. Default settings can be configured for each <a href=\":content-type\">type of content</a> on your site.','','none'),(6687,_binary 'The Node module gives users with the <em>Administer content types</em> permission the ability to <a href=\":content-new\">create new content types</a> in addition to the default ones already configured. Creating custom content types gives you the flexibility to add <a href=\":field\">fields</a> and configure default settings that suit the differing needs of various site content.','','none'),(6688,_binary 'The <a href=\":content\">Content</a> page lists your content, allowing you add new content, filter, edit or delete existing content, or perform bulk operations on existing content.','','none'),(6689,_binary 'The Node module makes a number of permissions available for each content type, which can be set by role on the <a href=\":permissions\">permissions page</a>.','','none'),(6690,_binary 'If the site is experiencing problems with permissions to content, you may have to rebuild the permissions cache. Rebuilding will remove all privileges to content and replace them with permissions based on the current modules and settings. Rebuilding may take some time if there is a lot of content or complex permission settings. After rebuilding has completed, content will automatically use the new permissions. <a href=\":rebuild\">Rebuild permissions</a>','','none'),(6691,_binary 'Maintain the types of content available and the fields that are associated with those types.','','10.5.6'),(6692,_binary 'No content types available. <a href=\":link\">Add content type</a>.','','none'),(6693,_binary 'Node from URL','','none'),(6694,_binary 'The Options module allows you to create fields where data values are selected from a fixed list of options. Usually these items are entered through a select list, checkboxes, or radio buttons. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":options_do\">online documentation for the Options module</a>.','','none'),(6695,_binary 'The <em>settings</em> and the <em>display</em> of the list fields can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6696,_binary 'The Internal Page Cache module caches pages for anonymous users in the database. For more information, see the <a href=\":pagecache-documentation\">online documentation for the Internal Page Cache module</a>.','','none'),(6697,_binary 'Pages are usually identical for all anonymous users, while they can be personalized for each authenticated user. This is why entire pages can be cached for anonymous users, whereas they will have to be rebuilt for every authenticated user.','','none'),(6698,_binary 'To speed up your site for authenticated users, see the <a href=\":dynamic_page_cache-help\">Dynamic Page Cache module</a>.','','none'),(6699,_binary 'The Path module allows you to specify an alias, or custom URL, for any existing internal system path. Aliases should not be confused with URL redirects, which allow you to forward a changed or inactive URL to a new URL. In addition to making URLs more readable, aliases also help search engines index content more effectively. Multiple aliases may be used for a single internal system path. To automate the aliasing of paths, you can install the contributed module <a href=\":pathauto\">Pathauto</a>. For more information, see the <a href=\":path\">online documentation for the Path module</a>.','','none'),(6700,_binary 'If you create or edit a taxonomy term you can add an alias (for example <em>music/jazz</em>) in the field \"URL alias\". When creating or editing content you can add an alias (for example <em>about-us/team</em>) under the section \"URL path settings\" in the field \"URL alias\". Aliases for any other path can be added through the page <a href=\":aliases\">URL aliases</a>. To add aliases a user needs the permission <a href=\":permissions\">Create and edit URL aliases</a>.','','none'),(6701,_binary 'The Path module provides a way to search and view a <a href=\":aliases\">list of all aliases</a> that are in use on your website. Aliases can be added, edited and deleted through this list.','','none'),(6702,_binary 'The internal system path.','','none'),(6703,_binary 'The path alias.','','none'),(6704,_binary 'The Responsive Image module provides an image formatter that allows browsers to select which image file to display based on media queries or which image file types the browser supports, using the HTML 5 picture and source elements and/or the sizes, srcset and type attributes. For more information, see the <a href=\":responsive_image\">online documentation for the Responsive Image module</a>.','','none'),(6705,_binary 'By creating responsive image styles you define which options the browser has in selecting which image file to display. In most cases this means providing different image sizes based on the viewport size. On the <a href=\":responsive_image_style\">Responsive image styles</a> page, click <em>Add responsive image style</em> to create a new style. First choose a label, a fallback image style and a breakpoint group and click Save.','','none'),(6706,_binary 'Below the Sizes field you can choose multiple image styles so the browser can choose the best image file size to fill the space defined in the Sizes field. Typically you will want to use image styles that resize your image to have options that range from the smallest px width possible for the space the image will appear in to the largest px width possible, with a variety of widths in between. You may want to provide image styles with widths that are 1.5x to 2x the space available in the layout to account for high resolution screens. Image styles can be defined on the <a href=\":image_styles\">Image styles page</a> that is provided by the <a href=\":image_help\">Image module</a>.','','none'),(6707,_binary 'After defining responsive image styles, you can use them in the display settings for your Image fields, so that the site displays responsive images using the HTML5 picture tag. Open the Manage display page for the entity type (content type, taxonomy vocabulary, etc.) that the Image field is attached to. Choose the format <em>Responsive image</em>, click the Edit icon, and select one of the responsive image styles that you have created. For general information on how to manage fields and their display see the <a href=\":field_ui\">Field UI module help page</a>. For background information about entities and fields see the <a href=\":field_help\">Field module help page</a>.','','none'),(6708,_binary 'See the <a href=\":responsive_image_help\">Responsive Image help page</a> for information on the sizes attribute.','','none'),(6709,_binary 'Configure Responsive Image Styles','','none'),(6710,_binary 'The Search module provides the ability to set up search pages based on plugins provided by other modules. In Drupal core, there are two page-type plugins: the Content page type provides keyword searching for content managed by the Node module, and the Users page type provides keyword searching for registered users. Contributed modules may provide other page-type plugins. For more information, see the <a href=\":search-module\">online documentation for the Search module</a>.','','none'),(6711,_binary 'To configure search pages, visit the <a href=\":search-settings\">Search pages page</a>. In the Search pages section, you can add a new search page, edit the configuration of existing search pages, enable and disable search pages, and choose the default search page. Each enabled search page has a URL path starting with <em>search</em>, and each will appear as a tab or local task link on the <a href=\":search-url\">search page</a>; you can configure the text that is shown in the tab. In addition, some search page plugins have additional settings that you can configure for each search page.','','none'),(6712,_binary 'Some search page plugins, such as the core Content search page, index searchable text using the Drupal core search index, and will not work unless content is indexed. Indexing is done during <em>cron</em> runs, so it requires a <a href=\":cron\">cron maintenance task</a> to be set up. There are also several settings affecting indexing that can be configured on the <a href=\":search-settings\">Search pages page</a>: the number of items to index per cron run, the minimum word length to index, and how to handle Chinese, Japanese, and Korean characters.','','none'),(6713,_binary 'Users with <a href=\":search_permission\">Use search</a> permission can use the Search block and <a href=\":search\">Search page</a>. Users with the <a href=\":node_permission\">View published content</a> permission can use configured search pages of type <em>Content</em> to search for content containing exact keywords; in addition, users with <a href=\":search_permission\">Use advanced search</a> permission can use more complex search filtering. Users with the <a href=\":user_permission\">View user information</a> permission can use configured search pages of type <em>Users</em> to search for active users containing the keyword anywhere in the username, and users with the <a href=\":user_permission\">Administer users</a> permission can search for active and blocked users, by email address or username keyword.','','none'),(6714,_binary 'By default, the Search module only supports exact keyword matching in content searches. You can modify this behavior by installing a language-specific stemming module for your language (such as <a href=\":porterstemmer_url\">Porter Stemmer</a> for American English), which allows words such as walk, walking, and walked to be matched in the Search module. Another approach is to use a third-party search technology with stemming or partial word matching features built in, such as <a href=\":solr_url\">Apache Solr</a> or <a href=\":sphinx_url\">Sphinx</a>. There are also contributed modules that provide additional search pages. These and other <a href=\":contrib-search\">search-related contributed modules</a> can be downloaded by visiting Drupal.org.','','none'),(6715,_binary '… @excerpt … @excerpt …','','none'),(6716,_binary 'This module does not have a user interface. It is used by other modules which need to serialize data, such as <a href=\":rest\">REST</a>.','','none'),(6717,_binary 'For more information, see the <a href=\":doc_url\">online documentation for the Serialization module</a>.','','none'),(6718,_binary 'The Shortcut module allows users to create sets of <em>shortcut</em> links to commonly-visited pages of the site. Shortcuts are contained within <em>sets</em>. Each user with <em>Select any shortcut set</em> permission can select a shortcut set created by anyone at the site. For more information, see the <a href=\":shortcut\">online documentation for the Shortcut module</a>.','','none'),(6719,_binary 'Users with the <em>Administer shortcuts</em> permission can manage shortcut sets and edit the shortcuts within sets from the <a href=\":shortcuts\">Shortcuts administration page</a>.','','none'),(6720,_binary 'Define which shortcut set you are using on the <a href=\":shortcut-link\">Shortcuts tab</a> of your account page.','','none'),(6721,_binary 'No shortcuts available. <a href=\":link\">Add a shortcut</a>','','none'),(6722,_binary 'You are now using the new %set_name shortcut set. You can edit it from this page or <a href=\":switch-url\">switch back to a different one.</a>','','none'),(6723,_binary 'The link for this shortcut.','','none'),(6724,_binary 'The title for this shortcut.','','none'),(6725,_binary 'The weight for this shortcut','','none'),(6726,_binary 'The name under which the set\'s links are stored.','','none'),(6727,_binary 'The title of the set.','','none'),(6728,_binary 'The users.uid for this set.','','none'),(6729,_binary 'The shortcut_set.set_name that will be displayed for this user.','','none'),(6730,_binary 'The Statistics module shows you how often content is viewed. This is useful in determining which pages of your site are most popular. For more information, see the <a href=\":statistics_do\">online documentation for the Statistics module</a>.','','none'),(6731,_binary 'The module includes a <em>Popular content</em> block that displays the most viewed pages today and for all time, and the last content viewed. To use the block, enable <em>Count content views</em> on the <a href=\":statistics-settings\">Statistics page</a>, and then you can enable and configure the block on the <a href=\":blocks\">Block layout page</a>.','','none'),(6732,_binary 'The Statistics module includes a counter for each page that increases whenever the page is viewed. To use the counter, enable <em>Count content views</em> on the <a href=\":statistics-settings\">Statistics page</a>, and set the necessary <a href=\":permissions\">permissions</a> (<em>View content hits</em>) so that the counter is visible to the users.','','none'),(6733,_binary 'How long any statistics may be cached, i.e. the refresh interval','','none'),(6734,_binary 'Version: @module-version','','10.5.6'),(6735,_binary 'Requires: @module-list','','10.5.6'),(6736,_binary 'Required by: @module-list','','10.5.6'),(6737,_binary 'This theme requires PHP version @php_required and is incompatible with PHP version @php_version.','','none'),(6738,_binary 'The System module is integral to the site: it provides user interfaces for many core systems and settings, as well as the basic administrative menu structure. For more information, see the <a href=\":system\">online documentation for the System module</a>.','','none'),(6739,_binary 'Users with appropriate permission can install and uninstall modules from the <a href=\":modules\">Extend page</a>. Depending on which distribution or installation profile you choose when you install your site, several modules are installed and others are provided but not installed. Each module provides a discrete set of features; modules may be installed or uninstalled depending on the needs of the site. Many additional modules contributed by members of the Drupal community are available for download from the <a href=\":drupal-modules\">Drupal.org module page</a>. Note that uninstalling a module is a destructive action: when you uninstall a module, you will permanently lose all data connected to the module.','','none'),(6740,_binary 'Users with appropriate permission can install and uninstall themes on the <a href=\":themes\">Appearance page</a>. Themes determine the design and presentation of your site. Depending on which distribution or installation profile you choose when you install your site, a default theme is installed, and possibly a different theme for administration pages. Other themes are provided but not installed, and additional contributed themes are available at the <a href=\":drupal-themes\">Drupal.org theme page</a>.','','none'),(6741,_binary 'When you are performing site maintenance, you can prevent non-administrative users (including anonymous visitors) from viewing your site by putting it in <a href=\":maintenance-mode\">Maintenance mode</a>. This will prevent unauthorized users from making changes to the site while you are performing maintenance, or from seeing a broken site while updates are in progress.','','none'),(6742,_binary 'On the <a href=\":performance-page\">Performance page</a>, the site can be configured to aggregate CSS and JavaScript files, making the total request size smaller. Note that, for small- to medium-sized websites, the <a href=\":page-cache\">Internal Page Cache module</a> should be installed so that pages are efficiently cached and reused for anonymous users. Finally, for websites of all sizes, the <a href=\":dynamic-page-cache\">Dynamic Page Cache module</a> should also be installed so that the non-personalized parts of pages are efficiently cached (for all users).','','none'),(6743,_binary 'Your site has several file directories, which are used to store and process uploaded and generated files. The <em>public</em> file directory, which is configured in your settings.php file, is the default place for storing uploaded files. Links to files in this directory contain the direct file URL, so when the files are requested, the web server will send them directly without invoking your site code. This means that the files can be downloaded by anyone with the file URL, so requests are not access-controlled but they are efficient. The <em>private</em> file directory, also configured in your settings.php file and ideally located outside the site web root, is access controlled. Links to files in this directory are not direct, so requests to these files are mediated by your site code. This means that your site can check file access permission for each file before deciding to fulfill the request, so the requests are more secure, but less efficient. You should only use the private storage for files that need access control, not for files like your site logo and background images used on every page. The <em>temporary</em> file directory is used internally by your site code for various operations, and is configured on the <a href=\":file-system\">File system settings</a> page. You can also see the configured public and private file directories on this page, and choose whether public or private should be the default for uploaded files.','','none'),(6744,_binary 'On the <a href=\":toolkit\">Image toolkit page</a>, you can select and configure the PHP toolkit used to manipulate images. Depending on which distribution or installation profile you choose when you install your site, the GD2 toolkit and possibly others are included; other toolkits may be provided by contributed modules.','','none'),(6745,_binary 'Set and configure the default theme for your website.  Alternative <a href=\":themes\">themes</a> are available.','','10.5.6'),(6746,_binary 'You can place blocks for each theme on the <a href=\":blocks\">block layout</a> page.','','10.5.6'),(6747,_binary 'Here you can find a short overview of your site\'s parameters as well as any problems detected with your installation. It may be useful to copy and paste this information into support requests filed on Drupal.org\'s support forums and project issue queues. Before filing a support request, ensure that your web server meets the <a href=\":system-requirements\">system requirements.</a>','','none'),(6748,_binary 'Configure your <a href=\":user-edit\">account time zone setting</a>.','','none'),(6749,_binary 'The minimum version of Apache needed to run Drupal without mod_rewrite enabled is 2.2.16. See the <a href=\":link\">enabling clean URLs</a> page for more information on mod_rewrite.','','none'),(6750,_binary 'Your server is capable of using clean URLs, but it is not enabled. Using clean URLs gives an improved user experience and is recommended. <a href=\":link\">Enable clean URLs</a>','','none'),(6751,_binary '@phpversion (<a href=\":url\">more information</a>)','','none'),(6752,_binary 'Drupal requires you to enable the PHP extensions in the following list (see the <a href=\":system_requirements\">system requirements page</a> for more information):','','none'),(6753,_binary 'PHP OPcode caching','','none'),(6754,_binary 'Your web server does not appear to support PDO (PHP Data Objects). Ask your hosting provider if they support the native PDO extension. See the <a href=\":link\">system requirements</a> page for more information.','','none'),(6755,_binary 'Your web server does not appear to support any common PDO database extensions. Check with your hosting provider to see if they support PDO (PHP Data Objects) and offer any databases that <a href=\":drupal-databases\">Drupal supports</a>.','','none'),(6756,_binary 'Your web server seems to have the wrong version of PDO installed. Drupal requires the PDO extension from PHP core. This system has the older PECL version. See the <a href=\":link\">system requirements</a> page for more information.','','none'),(6757,_binary 'For more information, see the online handbook entry for <a href=\":memory-limit\">increasing the PHP memory limit</a>.','','none'),(6758,_binary 'See <a href=\":url\">@url</a> for information about the recommended .htaccess file which should be added to the %directory directory to help protect against arbitrary code execution.','','none'),(6759,_binary 'Last run @time ago','','none'),(6760,_binary 'For more information, see the online handbook entry for <a href=\":cron-handbook\">configuring cron jobs</a>.','','none'),(6761,_binary 'You may need to set the correct directory at the <a href=\":admin-file-system\">file system settings page</a> or change the current directory\'s permissions so that it is writable.','','none'),(6762,_binary 'An automated attempt to create this directory failed, possibly due to a permissions problem. To proceed with the installation, either create the directory and modify its permissions manually or ensure that the installer has the permissions to create it automatically. For more information, see INSTALL.txt or the <a href=\":handbook_url\">online handbook</a>.','','none'),(6763,_binary 'Some modules have database schema updates to install. You should run the <a href=\":update\">database update script</a> immediately.','','none'),(6764,_binary 'The trusted_host_patterns setting is not configured in settings.php. This can lead to security vulnerabilities. It is <strong>highly recommended</strong> that you configure this. See <a href=\":url\">Protecting against HTTP HOST Header attacks</a> for more information.','','none'),(6765,_binary 'Put your site into <a href=\":url\">maintenance mode</a>.','','none'),(6766,_binary 'All errors have been <a href=\":url\">logged</a>.','','none'),(6767,_binary 'Updates were attempted. If you see no failures below, you may proceed happily back to your <a href=\":url\">site</a>. Otherwise, you may need to update your database manually.','','none'),(6768,_binary 'One or more problems were detected with your Drupal installation. Check the <a href=\":status\">status report</a> for more information.','','none'),(6769,_binary 'Screenshot for @theme theme','','10.5.6'),(6770,_binary 'Settings for @theme theme','','10.5.6'),(6771,_binary 'Uninstall @theme theme','','10.5.6'),(6772,_binary 'Set @theme as default theme','','10.5.6'),(6773,_binary 'Install @theme theme','','10.5.6'),(6774,_binary 'Install @theme as default theme','','10.5.6'),(6775,_binary 'More information about setting up scheduled tasks can be found by <a href=\":url\">reading the cron tutorial on drupal.org</a>.','','none'),(6776,_binary 'This version is not compatible with Drupal @core_version and should be replaced.','','none'),(6777,_binary 'This module requires PHP version @php_required and is incompatible with PHP version @php_version.','','none'),(6778,_binary 'Defined on the <a href=\":information\">Site Information</a> page.','','10.5.6'),(6779,_binary 'Powered by <a href=\":poweredby\">Drupal</a>','','10.5.6'),(6780,_binary 'The Taxonomy module allows users who have permission to create and edit content to categorize (tag) content of that type. Users who have the <em>Administer vocabularies and terms</em> <a href=\":permissions\" title=\"Taxonomy module permissions\">permission</a> can add <em>vocabularies</em> that contain a set of related <em>terms</em>. The terms in a vocabulary can either be pre-set by an administrator or built gradually as content is added and edited. Terms may be organized hierarchically if desired.','','none'),(6781,_binary 'For more information, see the <a href=\":taxonomy\">online documentation for the Taxonomy module</a>.','','none'),(6782,_binary 'Users who have the <em>Administer vocabularies and terms</em> permission can add and edit vocabularies from the <a href=\":taxonomy_admin\">Taxonomy administration page</a>. Vocabularies can be deleted from their <em>Edit vocabulary</em> page. Users with the <em>Taxonomy term: Administer fields</em> permission may add additional fields for terms in that vocabulary using the <a href=\":field_ui\">Field UI module</a>.','','none'),(6783,_binary 'Users who have the <em>Administer vocabularies and terms</em> permission or the <em>Edit terms</em> permission for a particular vocabulary can add, edit, and organize the terms in a vocabulary from a vocabulary\'s term listing page, which can be accessed by going to the <a href=\":taxonomy_admin\">Taxonomy administration page</a> and clicking <em>List terms</em> in the <em>Operations</em> column. Users must have the <em>Administer vocabularies and terms</em> permission or the <em>Delete terms</em> permission for a particular vocabulary to delete terms.','','none'),(6784,_binary 'A user with the <em>Administer fields</em> permission for a certain entity type may add <em>Taxonomy term</em> reference fields to the entity type, which will allow entities to be classified using taxonomy terms. See the <a href=\":entity_reference\">Entity Reference help</a> for more information about reference fields. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them.','','none'),(6785,_binary 'See the <a href=\":entity_reference\">Entity Reference help</a> page for the field widgets and formatters that can be configured for any reference field on the <em>Manage display</em> and <em>Manage form display</em> pages. Taxonomy additionally provides an <em>RSS category</em> formatter that displays nothing when the entity item is displayed as HTML, but displays an RSS category instead of a list when the entity item is displayed in an RSS feed.','','none'),(6786,_binary 'No vocabularies available. <a href=\":link\">Add vocabulary</a>.','','none'),(6787,_binary 'No terms available. <a href=\":link\">Add term</a>.','','10.5.6'),(6788,_binary 'Format of the term description.','','none'),(6789,_binary 'Module responsible for the vocabulary.','','none'),(6790,_binary 'The Telephone module allows you to create fields that contain telephone numbers. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":telephone_documentation\">online documentation for the Telephone module</a>.','','none'),(6791,_binary 'The <em>settings</em> and the <em>display</em> of the telephone field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6792,_binary 'The Text module allows you to create short and long text fields with optional summaries. See the <a href=\":field\">Field module help</a> and the <a href=\":field_ui\">Field UI help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=\":text_documentation\">online documentation for the Text module</a>.','','none'),(6793,_binary 'The <em>settings</em> and <em>display</em> of the text field can be configured separately. See the <a href=\":field_ui\">Field UI help</a> for more information on how to manage fields and their display.','','none'),(6794,_binary 'If you choose <em>Text (plain)</em> or <em>Text (plain, long)</em> you restrict the input to <em>Plain text</em> only. If you choose <em>Text (formatted)</em>, <em>Text (formatted, long)</em>, or <em>Text (formatted, long with summary)</em> you allow users to write formatted text. Which options are available to individual users depends on the settings on the <a href=\":formats\">Text formats and editors page</a>.','','none'),(6795,_binary 'Number of summary rows: @rows','','10.5.6'),(6796,_binary 'The Toolbar module provides a toolbar for site administrators, which displays tabs and trays provided by the Toolbar module itself and other modules. For more information, see the <a href=\":toolbar_docs\">online documentation for the Toolbar module</a>.','','none'),(6797,_binary 'The Tour module provides users with guided tours of the site interface. Each tour consists of several tips that highlight elements of the user interface, guide the user through a workflow, or explain key concepts of the website. For more information, see the <a href=\':tour\'>online documentation for the Tour module</a>.','','none'),(6798,_binary 'Tours can be written as YAML-documents with a text editor, or using the contributed <a href=\':tour_ui\'>Tour UI</a> module. For more information, see <a href=\':doc_url\'>the online documentation for writing tours</a>.','','none'),(6799,_binary '@tour_item of @total','','none'),(6800,_binary 'The Activity Tracker module displays the most recently added and updated content on your site, and allows you to follow new content created by each user. This module has no configuration options. For more information, see the <a href=\":tracker\">online documentation for the Activity Tracker module</a>.','','none'),(6801,_binary 'The <a href=\":recent\">Recent content</a> page shows new and updated content in reverse chronological order, listing the content type, title, author\'s name, number of comments, and time of last update. Content is considered updated when changes occur in the text, or when new comments are added. The <em>My recent content</em> tab limits the list to the currently logged-in user.','','none'),(6802,_binary 'The {node}.nid this record tracks.','','none'),(6803,_binary 'Boolean indicating whether the node is published.','','none'),(6804,_binary 'The Unix timestamp when the node was most recently saved or commented on.','','none'),(6805,_binary 'The {user}.nid this record tracks.','','none'),(6806,_binary 'The {users}.uid of the node author or commenter.','','none'),(6807,_binary 'The Unix timestamp when the user was most recently saved or commented on.','','none'),(6808,_binary 'Uninstalled modules','','none'),(6809,_binary 'Uninstalled themes','','none'),(6810,_binary 'The <a href=\":update-report\">Available updates report</a> displays core, contributed modules, and themes for which there are new releases available for download. On the report page, you can also check manually for updates. You can configure the frequency of update checks, which are performed during cron runs, and whether notifications are sent on the <a href=\":update-settings\">Update Manager settings page</a>.','','none'),(6811,_binary 'The Update Manager module allows administrators to perform updates directly from the <a href=\":update-page\">Update page</a>. It lists all available updates, and you can confirm whether you want to download them. If you don\'t have sufficient access rights to your web server, you could be prompted for your FTP/SSH password. Afterwards the files are transferred into your site installation, overwriting your old files. Direct links to the Update page are also displayed on the <a href=\":modules_page\">Extend page</a> and the <a href=\":themes_page\">Appearance page</a>.','','none'),(6812,_binary 'No update information available. <a href=\":run_cron\">Run cron</a> or <a href=\":check_manually\">check manually</a>.','','none'),(6813,_binary 'New release(s) available for @site_name','','none'),(6814,_binary 'Your site is currently configured to send these emails when any updates are available. To get notified only for security updates, @url.','','none'),(6815,_binary 'Your site is currently configured to send these emails only when security updates are available. To get notified for any available updates, @url.','','none'),(6816,_binary 'There was a problem checking <a href=\":update-report\">available updates</a> for Drupal.','','none'),(6817,_binary 'There was a problem checking <a href=\":update-report\">available updates</a> for your modules or themes.','','none'),(6818,_binary '%archive_file contains a version of %names that is not compatible with Drupal @version.%archive_file contains versions of modules or themes that are not compatible with Drupal @version: %names','','none'),(6819,_binary 'Update Manager settings','','none'),(6820,_binary 'Check for updates of uninstalled modules and themes','','none'),(6821,_binary 'You can find <a href=\":module_url\">modules</a> and <a href=\":theme_url\">themes</a> on <a href=\":drupal_org_url\">drupal.org</a>. The following file extensions are supported: %extensions.','','none'),(6822,_binary 'Back up your database and site before you continue. <a href=\":backup_url\">Learn how</a>.','','none'),(6823,_binary 'Deprecated: User Name','','10.5.6'),(6824,_binary 'Deprecated: Use account-name or display-name instead.','','10.5.6'),(6825,_binary 'The display name of the user account.','','10.5.6'),(6826,_binary 'The User module allows users to register, log in, and log out. It also allows users with proper permissions to manage user roles and permissions. For more information, see the <a href=\":user_docs\">online documentation for the User module</a>.','','none'),(6827,_binary 'Through the <a href=\":people\">People administration page</a> you can add and cancel user accounts and assign users to roles. By editing one particular user you can change their username, email address, password, and information in other fields.','','none'),(6828,_binary 'After creating roles, you can set permissions for each role on the <a href=\":permissions_user\">Permissions page</a>. Granting a permission allows users who have been assigned a particular role to perform an action on the site, such as viewing content, editing or creating  a particular type of content, administering settings for a particular module, or using a particular function of the site (such as search).','','none'),(6829,_binary 'Because User accounts are an entity type, you can extend them by adding fields through the Manage fields tab on the <a href=\":accounts\">Account settings page</a>. By adding fields for e.g., a picture, a biography, or address, you can a create a custom profile for the users of the website. For background information on entities and fields, see the <a href=\":field_help\">Field module help page</a>.','','none'),(6830,_binary 'A role defines a group of users that have certain privileges. These privileges are defined on the <a href=\":permissions\">Permissions page</a>. Here, you can define the names and the display sort order of the roles on your site. It is recommended to order roles from least permissive (for example, Anonymous user) to most permissive (for example, Administrator user). Users who are not logged in have the Anonymous user role. Users who are logged in have the Authenticated user role, plus any other roles granted to their user account.','','10.5.6'),(6831,_binary 'Make it at least 12 characters','','10.5.6'),(6832,_binary 'Configure site-wide settings and behavior for user accounts and registration. This includes account cancellation methods, the content of user emails and fields attached to users.','','10.5.6'),(6833,_binary 'Manage all user accounts. This includes editing all user information, changes of email addresses and passwords, issuing emails to users and blocking and deleting user accounts.','','10.5.6'),(6834,_binary 'Users with the %select-cancel-method or %administer-users <a href=\":permissions-url\">permissions</a> can override this default method.','','none'),(6835,_binary 'Available variables are: [site:name], [site:url], [user:display-name], [user:account-name], [user:mail], [site:login-url], [site:url-brief], [user:edit-url], [user:one-time-login-url], [user:cancel-url].','','none'),(6836,_binary 'Created a new user account for <a href=\":url\">%name</a>. No email has been sent.','','10.5.6'),(6837,_binary 'The new user <a href=\":url\">%name</a> was created without an email address, so no welcome message was sent.','','none'),(6838,_binary 'A welcome message with further instructions has been emailed to the new user <a href=\":url\">%name</a>.','','none'),(6839,_binary 'Password reset instructions will be sent to your registered email address.','','none'),(6840,_binary 'Send password reset instructions via email.','','none'),(6841,_binary 'Also known as:','','10.5.6'),(6842,_binary '@label (@name:@column)','','10.5.6'),(6843,_binary '@label:@column','','none'),(6844,_binary '@label (@name:delta)','','10.5.6'),(6845,_binary 'For more information, see the <a href=\":views\">online documentation for the Views module</a>.','','none'),(6846,_binary 'Contributed projects that support the Views module can be found in the <a href=\":node\">online documentation for Views-related contributed modules</a>.','','none'),(6847,_binary 'Changing the title here means it cannot be dynamically altered anymore. (Try changing it directly in <a href=\":url\">@name</a>.)','','10.5.6'),(6848,_binary 'This link is provided by the Views module. The path can be changed by editing the view <a href=\":url\">@label</a>','','none'),(6849,_binary '@type language selected for page','','none'),(6850,_binary 'Will not be accessible.','','none'),(6851,_binary '@code (@title)','','none'),(6852,_binary 'The following tokens are available. You may use Twig syntax in this field.','','10.5.6'),(6853,_binary 'Override the view and other argument titles. You may use Twig syntax in this field as well as the \"arguments\" and \"raw_arguments\" arrays.','','10.5.6'),(6854,_binary 'Override the view and other argument titles. You may use Twig syntax in this field.','','10.5.6'),(6855,_binary 'The following replacement tokens are available for this argument.','','10.5.6'),(6856,_binary 'The category this block will appear under on the <a href=\":href\">blocks placement page</a>.','','none'),(6857,_binary 'Separate multiple classes by spaces.','','10.5.6'),(6858,_binary 'You may also adjust the @settings for the currently selected access restriction.','','none'),(6859,_binary 'You may also adjust the @settings for the currently selected cache mechanism.','','none'),(6860,_binary 'You may also adjust the @settings for the currently selected style.','','10.5.6'),(6861,_binary 'You may also adjust the @settings for the currently selected row style.','','10.5.6'),(6862,_binary 'The following tokens are available for this link. You may use Twig syntax in this field.','','none'),(6863,_binary 'You may also adjust the @settings for the currently selected pager.','','10.5.6'),(6864,_binary 'An offset from the current time such as \"@example1\" or \"@example2\"','','none'),(6865,_binary 'The Views UI module provides an interface for managing views for the <a href=\":views\">Views module</a>. For more information, see the <a href=\":handbook\">online documentation for the Views UI module</a>.','','none'),(6866,_binary 'Views can be enabled or disabled from the <a href=\":list\">Views list page</a>. To enable a view, find the view within the \"Disabled\" list and select the \"Enable\" operation. To disable a view find the view within the \"Enabled\" list and select the \"Disable\" operation.','','none'),(6867,_binary 'Views can be exported and imported as configuration files by using the <a href=\":config\">Configuration Manager module</a>.','','none'),(6868,_binary 'Advanced Views settings','','none'),(6869,_binary 'View @display_title','','10.5.6'),(6870,_binary 'Duplicate as @type','','10.5.6'),(6871,_binary 'Add @display','','10.5.6'),(6872,_binary 'By breaking this lock, any unsaved changes made by @user will be lost.','','none'),(6873,_binary 'Account cancellation request for [user:display-name] at [site:name]','','10.5.6'),(6874,_binary 'Replacement login information for [user:display-name] at [site:name]','','10.5.6'),(6875,_binary 'Account details for [user:display-name] at [site:name]','','10.5.6'),(6876,_binary 'Account details for [user:display-name] at [site:name] (pending admin approval)','','10.5.6'),(6877,_binary '[user:display-name] has applied for an account.\n\n[user:edit-url]','','10.5.6'),(6878,_binary '[user:display-name],\n\nYour account at [site:name] has been activated.\n\nYou may now log in by clicking this link or copying and pasting it into your browser:\n\n[user:one-time-login-url]\n\nThis link can only be used once to log in and will lead you to a page where you can set your password.\n\nAfter setting your password, you will be able to log in at [site:login-url] in the future using:\n\nusername: [user:account-name]\npassword: Your password\n\n--  [site:name] team','','10.5.6'),(6879,_binary 'Account details for [user:display-name] at [site:name] (approved)','','10.5.6'),(6880,_binary 'Account details for [user:display-name] at [site:name] (blocked)','','10.5.6'),(6881,_binary '[user:display-name],\n\nYour account on [site:name] has been canceled.\n\n--  [site:name] team','','10.5.6'),(6882,_binary 'Account details for [user:display-name] at [site:name] (canceled)','','10.5.6'),(6883,_binary 'Hide logo','','none'),(6884,_binary '@display \'@id\': Component \'@name\' was disabled because its settings depend on removed dependencies.','','none'),(6885,_binary 'No widget available for: %type.','','none'),(6886,_binary 'Several special characters are allowed, including space, period (.), hyphen (-), apostrophe (\'), underscore (_), and the @ sign.','','10.5.6'),(6887,_binary 'Create tasks that the system can execute.','','none'),(6888,_binary 'The URL to which the user should be redirected. This can be an internal URL like /node/1234 or an external URL like @url.','','none'),(6889,_binary 'The Automated Cron module runs cron operations for your site using normal browser/page requests instead of having to set up a separate cron job. The Automated Cron module checks at the end of each server response when cron operation was last ran and, if it has been too long since last run, it executes the cron tasks after sending a server response. For more information, see the <a href=\":automated_cron-documentation\">online documentation for the Automated Cron module</a>.','','none'),(6890,_binary 'Configuring Automated Cron','','none'),(6891,_binary 'On the <a href=\":cron-settings\">Cron page</a>, you can set the frequency (time interval) for running cron jobs.','','none'),(6892,_binary 'Disabling Automated Cron','','none'),(6893,_binary 'To disable automated cron, the recommended method is to uninstall the module, to reduce site overhead. If you only want to disable it temporarily, you can set the frequency to Never on the Cron page, and then change the frequency back when you want to start it up again.','','none'),(6894,_binary 'Automated Cron','','none'),(6895,_binary 'Provides an automated way to run cron jobs, by executing them at the end of a server response.','','10.5.6'),(6896,_binary 'Automated cron settings','','none'),(6897,_binary 'Ban visits from specific IP addresses.','','none'),(6898,_binary 'You can place a new block in a region by selecting <em>Place block</em> on the <a href=\":blocks\">Block layout page</a>. Once a block is placed, it can be moved to a different region by drag-and-drop or by using the <em>Region</em> drop-down list, and then clicking <em>Save blocks</em>.','','none'),(6899,_binary 'Block placement is specific to each theme on your site. Changes will not be saved until you click <em>Save blocks</em> at the bottom of the page.','','10.5.6'),(6900,_binary 'Adding comment types','','none'),(6901,_binary 'Additional <em>comment types</em> can be created per entity sub-type and added on the <a href=\":field\">Comment types page</a>. If there are multiple comment types available you can select the appropriate one after adding a <em>Comments field</em>.','','none'),(6902,_binary 'Compare the configuration uploaded to your sync directory with the active configuration before completing the import.','','none'),(6903,_binary 'Upload a full site configuration archive to the sync directory. It can then be compared and imported on the Synchronize page.','','none'),(6904,_binary 'The Database Logging module logs system events in the Drupal database. Monitor your site or debug site problems on this page.','','none'),(6905,_binary 'The Internal Dynamic Page Cache module caches pages for all users in the database, handling dynamic content correctly. For more information, see the <a href=\":dynamic_page_cache-documentation\">online documentation for the Internal Dynamic Page Cache module</a>.','','none'),(6906,_binary 'The module requires no configuration. Every part of the page contains metadata that allows Internal Dynamic Page Cache to figure this out on its own.','','none'),(6907,_binary '<strong>Entity Reference</strong> fields allow you to create fields that contain links to other entities (such as content items, taxonomy terms, etc.) within the site. This allows you, for example, to include a link to a user within a content item. For more information, see <a href=\":er_do\">the online documentation for the Entity Reference module</a>.','','none'),(6908,_binary 'Enable custom storage','','none'),(6909,_binary 'An instance-specific widget type','','none'),(6910,_binary 'Widget types @types are used in Drupal 6 field instances: widget type @selected_type applied to the Drupal 8 base field','','none'),(6911,_binary 'You can define which users will be able to use each text format by selecting roles. To ensure security, anonymous and untrusted users should only have access to text formats that restrict them to either plain text or a safe set of HTML tags. This is because HTML tags can allow embedding malicious links or scripts in text. More trusted registered users may be granted permission to use less restrictive text formats in order to create rich text. <strong>Improper text format configuration is a security risk.</strong>','','none'),(6912,_binary 'Each text format uses filters that add, remove, or transform elements within user-entered text. For example, one filter removes unapproved HTML tags, while another transforms URLs into clickable links. Filters are applied in a specific order. They do not change the <em>stored</em> content: they define how it is processed and displayed.','','none'),(6913,_binary 'Text formats define how text is filtered for output and how HTML tags and other text is displayed, replaced, or removed. <strong>Improper text format configuration is a security risk.</strong> Learn more on the <a href=\":filter_help\">Filter module help page</a>.','','none'),(6914,_binary 'A text format contains filters that change the display of user input; for example, stripping out malicious HTML or making URLs clickable. Filters are executed from top to bottom and the order is important, since one filter may prevent another filter from doing its job. For example, when URLs are converted into links before disallowed HTML tags are removed, all links may be removed. When this happens, the order of filters may need to be rearranged.','','none'),(6915,_binary 'Configure how content is filtered when displayed, including which HTML tags are rendered, and enable module-provided filters.','','none'),(6916,_binary 'A list of HTML tags that can be used. By default only the <em>lang</em> and <em>dir</em> attributes are allowed for all HTML tags. Each HTML tag may have attributes which are treated as allowed attribute names for that HTML tag. Each attribute may allow all values, or only allow specific values. Attribute names or values may be written as a prefix and wildcard like <em>jump-*</em>. JavaScript event attributes, JavaScript URLs, and CSS are always stripped.','','none'),(6917,_binary 'Configure languages for content, interface, and configuration.','','10.5.6'),(6918,_binary 'Overriding default English strings','','none'),(6919,_binary 'If translation is enabled for English, you can <em>override</em> the default English interface text strings in your site with other English text strings on the <a href=\":translate\">User interface translation</a> page. Translation is off by default for English, but you can turn it on by visiting the <em>Edit language</em> page for <em>English</em> from the <a href=\":languages\">Languages</a> page.','','none'),(6920,_binary 'Configure the import of translation files, and add or customize interface translations.','','10.5.6'),(6921,_binary 'Manage menus and menu links.','','10.5.6'),(6922,_binary '<q>Log in</q> for anonymous users','','10.5.6'),(6923,_binary 'Revert to earlier revision of a translation','','none'),(6924,_binary 'Are you sure you want to revert @language translation to the revision from %revision-date?','','none'),(6925,_binary 'Revert content shared among translations','','none'),(6926,_binary 'Add custom URLs to existing paths.','','10.5.6'),(6927,_binary '- None (original image) -','','none'),(6928,_binary 'Only items in the index will appear in search results. To build and maintain the index, a correctly configured <a href=\":cron\">cron maintenance task</a> is required.','','none'),(6929,_binary 'The minimum character length for a word to be added to the index. Searches must include a keyword of at least this length.','','none'),(6930,_binary 'Configure the logging of content statistics.','','none'),(6931,_binary 'Checking site status','','none'),(6932,_binary 'The <a href=\":status\">Status report</a> provides an overview of the configuration, status, and health of your site. Review this report to make sure there are not any problems to address, and to find information about the software your site and web server are using.','','none'),(6933,_binary 'In order for the site and its modules to continue to operate well, a set of routine administrative operations must run on a regular basis; these operations are known as <em>cron</em> tasks. On the <a href=\":cron\">Cron page</a>, you can configure cron to run periodically as part of server responses by installing the <em>Automated Cron</em> module, or you can turn this off and trigger cron from an outside process on your web server. You can verify the status of cron tasks by visiting the <a href=\":status\">Status report page</a>. For more information, see the <a href=\":handbook\">online documentation for configuring cron jobs</a>.','','none'),(6934,_binary 'Public file base URL','','10.5.6'),(6935,_binary 'The base URL that will be used for public file URLs. This can be changed in settings.php','','10.5.6'),(6936,_binary 'Machine name: <span dir=\"ltr\" class=\"table-filter-text-source\">@machine-name</span>','','10.5.6'),(6937,_binary 'The following reason prevents @module.module_name from being uninstalled:The following reasons prevent @module.module_name from being uninstalled:','','10.5.6'),(6938,_binary 'Configure default user account settings, including fields, registration requirements, and email messages.','','10.5.6'),(6939,_binary 'Too many failed login attempts from your IP address. This IP address is temporarily blocked. Try again later or <a href=\":url\">request a new password</a>.','','none'),(6940,_binary 'There has been more than one failed login attempt for this account. It is temporarily blocked. Try again later or <a href=\":url\">request a new password</a>.There have been more than @count failed login attempts for this account. It is temporarily blocked. Try again later or <a href=\":url\">request a new password</a>.','','none'),(6941,_binary 'Cache maximum age','','none'),(6942,_binary 'Creating and managing views','','none'),(6943,_binary 'Enabling and disabling views','','none'),(6944,_binary 'Exporting and importing views','','none'),(6945,_binary 'Links related to the active user account','','10.5.6'),(6946,_binary 'Administrative task links','','10.5.6'),(6947,_binary 'Site information links','','10.5.6'),(6948,_binary 'Site section links','','10.5.6'),(6949,_binary 'User tool links, often added by modules','','10.5.6'),(6950,_binary '[user:display-name],\n\nA request to reset the password for your account has been made at [site:name].\n\nYou may now log in by clicking this link or copying and pasting it into your browser:\n\n[user:one-time-login-url]\n\nThis link can only be used once to log in and will lead you to a page where you can set your password. It expires after one day and nothing will happen if it\'s not used.\n\n--  [site:name] team','','10.5.6'),(6951,_binary '[user:display-name],\n\nA site administrator at [site:name] has created an account for you. You may now log in by clicking this link or copying and pasting it into your browser:\n\n[user:one-time-login-url]\n\nThis link can only be used once to log in and will lead you to a page where you can set your password.\n\nAfter setting your password, you will be able to log in at [site:login-url] in the future using:\n\nusername: [user:name]\npassword: Your password\n\n--  [site:name] team','','10.5.6'),(6952,_binary '[user:display-name],\n\nThank you for registering at [site:name]. You may now log in by clicking this link or copying and pasting it into your browser:\n\n[user:one-time-login-url]\n\nThis link can only be used once to log in and will lead you to a page where you can set your password.\n\nAfter setting your password, you will be able to log in at [site:login-url] in the future using:\n\nusername: [user:name]\npassword: Your password\n\n--  [site:name] team','','10.5.6'),(6953,_binary 'Twig debug mode','','10.5.6'),(6954,_binary 'The language code.','','10.5.6'),(6955,_binary 'Delete %label','','none'),(6956,_binary 'Allow user to display all items','','10.5.6'),(6957,_binary 'Select and configure text editors, and how content is filtered when displayed.','','10.5.6'),(6958,_binary 'Recent comments.','','10.5.6'),(6959,_binary 'Find and manage files.','','10.5.6'),(6960,_binary 'Editing languages','','none'),(6961,_binary 'All content, by month.','','10.5.6'),(6962,_binary 'Recent content.','','10.5.6'),(6963,_binary 'All content promoted to the front page.','','10.5.6'),(6964,_binary 'All content, by letter.','','10.5.6'),(6965,_binary 'Content belonging to a certain taxonomy term.','','10.5.6'),(6966,_binary 'Shows a list of the newest user accounts on the site.','','10.5.6'),(6967,_binary 'Who\'s online block','','10.5.6'),(6968,_binary 'Shows the user names of the most recently active users, and the total number of active users.','','10.5.6'),(6969,_binary 'View edit page','','none'),(6970,_binary 'Max 1300x1300','','none'),(6971,_binary 'Max 2600x2600','','none'),(6972,_binary 'Max 325x325','','none'),(6973,_binary 'Max 650x650','','none'),(6974,_binary 'Narrow','','none'),(6975,_binary 'Files overview','','10.5.6'),(6976,_binary 'File usage information for {{ arguments.fid }}','','10.5.6'),(6977,_binary '<p>This page provides the ability to add common languages to your site.</p><p>If the desired language is not available, you can add a custom language.</p>','','none'),(6978,_binary '<p>Choose a language from the list, or choose \"Custom language...\" at the end of the list.</p><p>Click the \"Add language\" button when you are done choosing your language.</p><p>When adding a custom language, you will get an additional form where you can provide the name, code, and direction of the language.</p>','','none'),(6979,_binary 'Continuing on','','none'),(6980,_binary '<p>This page provides the ability to edit a language on your site, including custom languages.</p>','','none'),(6981,_binary '<p>You cannot change the code of a language on the site, since it is used by the system to keep track of the language.</p>','','none'),(6982,_binary '<p>The language name is used throughout the site for all users and is written in English. Names of built-in languages can be translated using the Interface Translation module, and names of both built-in and custom languages can be translated using the Configuration Translation module.</p>','','none'),(6983,_binary '<p>Choose if the language is a \"Left to right\" or \"Right to left\" language.</p><p>Note that not all themes support \"Right to left\" layouts, so test your theme if you are using \"Right to left\".</p>','','none'),(6984,_binary '<p>The \"Languages\" page allows you to add, edit, delete, and reorder languages for the site.</p>','','none'),(6985,_binary '<p>To add more languages to your site, click the \"Add language\" button.</p><p>Added languages will be displayed in the language list and can then be edited or deleted.</p>','','none'),(6986,_binary 'Reordering languages','','none'),(6987,_binary '<p>To reorder the languages on your site, use the drag icons next to each language.</p><p>The order shown here is the display order for language lists on the site such as in the language switcher blocks provided by the Interface Translation and Content Translation modules.</p><p>When you are done with reordering the languages, click the \"Save configuration\" button for the changes to take effect.</p>','','none'),(6988,_binary 'Set a language as default','','none'),(6989,_binary '<p>You can change the default language of the site by choosing one of your configured languages as default. The site will use the default language in situations where no choice is made but a language should be set, for example as the language of the displayed interface.</p>','','none'),(6990,_binary 'Modifying languages','','none'),(6991,_binary '<p>Operations are provided for editing and deleting your languages.</p><p>You can edit the name and the direction of the language.</p><p>Deleted languages can be added back at a later time. Deleting a language will remove all interface translations associated with it, and content in this language will be set to be language neutral. Note that you cannot delete the default language of the site.</p>','','none'),(6992,_binary 'Choose the language you want to translate.','','none'),(6993,_binary 'Enter the specific word or sentence you want to translate, you can also write just a part of a word.','','none'),(6994,_binary 'Filter the search','','none'),(6995,_binary 'You can search for untranslated strings if you want to translate something that isn\'t translated yet. If you want to modify an existing translation, you might want to search only for translated strings.','','none'),(6996,_binary 'Apply your search criteria','','none'),(6997,_binary 'To apply your search criteria, click on the <em>Filter</em> button.','','none'),(6998,_binary 'You can write your own translation in the text fields of the right column. Try to figure out in which context the text will be used in order to translate it in the appropriate way.','','none'),(6999,_binary 'Validate the translation','','none'),(7000,_binary 'When you have finished your translations, click on the <em>Save translations</em> button. You must save your translations, each time before changing the page or making a new search.','','none'),(7001,_binary '{{ arguments.created_year_month }}','','10.5.6'),(7002,_binary 'Find and manage content','','10.5.6'),(7003,_binary 'Welcome to [site:name]','','none'),(7004,_binary '{{ arguments.tid }}','','10.5.6'),(7005,_binary 'Name or email contains','','10.5.6'),(7006,_binary 'A list of new users','','10.5.6'),(7007,_binary 'There are currently @total users online.','','10.5.6'),(7008,_binary 'There are currently 0 users online.','','10.5.6'),(7009,_binary 'A list of users that are currently logged in.','','10.5.6'),(7010,_binary 'Manage view settings','','none'),(7011,_binary 'View or edit the configuration.','','none'),(7012,_binary 'Displays in this view','','none'),(7013,_binary 'A display is a way of outputting the results, e.g., as a page or a block. A view can contain multiple displays, which are listed here. The active display is highlighted.','','none'),(7014,_binary 'View administration','','none'),(7015,_binary 'Perform administrative tasks, including adding a description and creating a clone. Click the drop-down button to view the available options.','','none'),(7016,_binary 'Choose how to output results. E.g., choose <em>Content</em> to output each item completely, using your configured display settings. Or choose <em>Fields</em>, which allows you to output only specific fields for each result. Additional formats can be added by installing modules to <em>extend</em> Drupal\'s base functionality.','','none'),(7017,_binary 'If this view uses fields, they are listed here. You can click on a field to configure it.','','none'),(7018,_binary 'Filter your view','','none'),(7019,