6,_binary 'The image file is invalid or the image type is not allowed. Allowed types: %types','','none'),(7667,_binary 'The image was resized to fit within the maximum allowed dimensions of %dimensions pixels. The new dimensions of the resized image are %new_widthx%new_height pixels.','','none'),(7668,_binary 'The image was resized to fit within the maximum allowed height of %height pixels. The new dimensions of the resized image are %new_widthx%new_height pixels.','','none'),(7669,_binary 'The image was resized to fit within the maximum allowed width of %width pixels. The new dimensions of the resized image are %new_widthx%new_height pixels.','','none'),(7670,_binary 'The resized image is too small. The minimum dimensions are %dimensions pixels and after resizing, the image size will be %widthx%height pixels.','','none'),(7671,_binary 'The image is too small. The minimum dimensions are %dimensions pixels and the image size is %widthx%height pixels.','','none'),(7672,_binary 'One or more files could not be uploaded.','','none'),(7673,_binary 'Media display format settings','','none'),(7674,_binary 'Show playback controls','','none'),(7675,_binary 'Audio file display format settings','','none'),(7676,_binary 'Video file display format settings','','none'),(7677,_binary 'Replace the file name by its description when available','','none'),(7678,_binary 'Use description as link text','','none'),(7679,_binary 'Display the file using an HTML5 audio tag.','','none'),(7680,_binary 'Playback controls: %controls','','none'),(7681,_binary 'Multiple file display: Multiple HTML tags','','none'),(7682,_binary 'Multiple file display: One HTML tag with multiple sources','','none'),(7683,_binary 'Display the file using an HTML5 video tag.','','none'),(7684,_binary 'Root-relative file URL','','none'),(7685,_binary 'An entity field containing a file URI, and a computed root-relative file URL.','','none'),(7686,_binary '@title field is required if there is @uri input.','','none'),(7687,_binary 'The Media module manages the creation, editing, deletion, settings, and display of media. Items are typically images, documents, slideshows, YouTube videos, tweets, Instagram photos, etc. You can reference media items from any other content on your site. For more information, see the <a href=\":media\">online documentation for the Media module</a>.','','none'),(7688,_binary 'Listing media items','','none'),(7689,_binary 'Media items are listed at the <a href=\":media-collection\">media administration page</a>.','','none'),(7690,_binary 'Adding media to other content','','none'),(7691,_binary 'Users with permission to administer content types can add media support by adding a media reference field to the content type on the content type administration page. (The same is true of block types, taxonomy terms, user profiles, and other content that supports fields.) A media reference field can refer to any configured media type. It is possible to allow multiple media types in the same field.','','none'),(7692,_binary 'Differences between Media, File, and Image reference fields','','none'),(7693,_binary '<em>Media</em> reference fields offer several advantages over basic <em>File</em> and <em>Image</em> references:','','none'),(7694,_binary 'Media reference fields can reference multiple media types in the same field.','','none'),(7695,_binary 'Fields can also be added to media types themselves, which means that custom metadata like descriptions and taxonomy tags can be added for the referenced media. (Basic file and image fields do not support this.)','','none'),(7696,_binary 'Media types for audio and video files are provided by default, so there is no need for additional configuration to upload these media.','','none'),(7697,_binary 'Contributed or custom projects can provide additional media sources (such as third-party websites, Twitter, etc.).','','none'),(7698,_binary 'Existing media items can be reused on any other content items with a media reference field.','','none'),(7699,_binary 'For more information, see the <a href=\"@help_url\">Media help page</a>.','','10.5.6'),(7700,_binary 'Media Name','','none'),(7701,_binary '%type_name: Create new media','','10.5.6'),(7702,_binary '%type_name: Edit own media','','10.5.6'),(7703,_binary '%type_name: Edit any media','','10.5.6'),(7704,_binary '%type_name: Delete own media','','10.5.6'),(7705,_binary '%type_name: Delete any media','','10.5.6'),(7706,_binary '<em>The media source cannot be changed after the media type is created.</em>','','none'),(7707,_binary 'Use audio files for reusable media.','','none'),(7708,_binary 'Use video files for reusable media.','','none'),(7709,_binary 'The destination system contains data which was not created by a migration.','','none'),(7710,_binary 'Migrate Drupal settings','','none'),(7711,_binary 'source_module enforcement tags','','none'),(7712,_binary 'Old site','','none'),(7713,_binary 'The site you want to upgrade.','','none'),(7714,_binary 'New site','','none'),(7715,_binary 'Preparation steps','','none'),(7716,_binary 'WARNING: Content may be overwritten on your new site.','','none'),(7717,_binary 'I acknowledge I may lose data. Continue anyway.','','none'),(7718,_binary 'There is conflicting content of these types:','','none'),(7719,_binary 'On the <a href=\":cache-settings\">Performance page</a>, you can configure how long browsers and proxies may cache pages based on the Cache-Control header; this setting is ignored by the Internal Page Cache module, which caches pages permanently until invalidation, unless they carry an Expires header. There is no other configuration.','','none'),(7720,_binary 'The Settings Tray module allows users with the <a href=\":administer_block_permission\">Administer blocks</a> and <a href=\":contextual_permission\">Use contextual links</a> permissions to edit blocks without visiting a separate page. For more information, see the <a href=\":handbook_url\">online documentation for the Settings Tray module</a>.','','none'),(7721,_binary 'Editing blocks in place','','none'),(7722,_binary 'To edit blocks in place, either click the <strong>Edit</strong> button in the toolbar and then click on the block, or choose \"Quick edit\" from the block\'s contextual link. (See the <a href=\":contextual\">Contextual Links module help</a> for more information about how to use contextual links.)','','none'),(7723,_binary 'The Settings Tray for the block will open in a sidebar, with a compact form for configuring what the block shows.','','none'),(7724,_binary 'Save the form and the changes will be immediately visible on the page.','','none'),(7725,_binary 'The ID of the node to which these statistics apply.','','none'),(7726,_binary 'Specify the format of the syslog entry. Available variables are: <dl><dt><code>!base_url</code></dt><dd>Base URL of the site.</dd><dt><code>!timestamp</code></dt><dd>Unix timestamp of the log entry.</dd><dt><code>!type</code></dt><dd>The category to which this message belongs.</dd><dt><code>!ip</code></dt><dd>IP address of the user triggering the message.</dd><dt><code>!request_uri</code></dt><dd>The requested URI.</dd><dt><code>!referer</code></dt><dd>HTTP Referer if available.</dd><dt><code>!severity</code></dt><dd>The severity level of the event; ranges from 0 (Emergency) to 7 (Debug).</dd><dt><code>!uid</code></dt><dd>User ID.</dd><dt><code>!link</code></dt><dd>A link to associate with the message.</dd><dt><code>!message</code></dt><dd>The message to store in the log.</dd></dl>','','none'),(7727,_binary 'Either the path \'%path\' is invalid or you do not have access to it.','','none'),(7728,_binary '%capital_name contains the following terms.','','none'),(7729,_binary '%capital_name contains terms grouped under parent terms','','none'),(7730,_binary '%capital_name contains terms with multiple parents.','','none'),(7731,_binary 'Access the taxonomy vocabulary overview page','','10.5.6'),(7732,_binary 'Get an overview of all taxonomy vocabularies.',