INSERT INTO `search_dataset` VALUES (1,'es','help_search',' exportando la configuracion completa de su sitio objetivo create and download an archive containing all your site s configuration exported as yaml files see managing and deploying configuration for more information about configuration pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   exportar  clique exportar y guarde el archivo  ',0),(1,'es','node_search',' promocion2 promocion2 admin lun 26012026 2036 imagen  ',0),(2,'es','help_search',' exportando un unico elemento de configuracion objetivo exporta un unico elemento de configuracion a un archivo consulte managing and deploying configuration para obtener mas informacion sobre la configuracion pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de configuracion   exportar   elemento unico  select the configuration type that you want to export and then select the specific configuration name to export use your browser to copy the text in the box marked here is your configuration to the clipboard paste the copied text into a plaintext editor on your computer or other device and save it using the suggested file name below the text box  ',0),(2,'es','node_search',' tu mejor opcion peluqueria en la uci tu mejor opcion peluqueria en la uci admin mie 28012026 1733 imagen lorem ipsum dolor sit amet consectetur adipiscing elite sed do eiusmod tempor incididunt ut labore et dolore magna aliqua magna aliqua ver ofertas ',0),(3,'es','help_search',' importando la configuracion completa de su sitio objetivo importar la configuracion completa de su sitio desde un archivo como uno que haya sido exportado previamente ver exportando la configuracion completa de su sitio consulte managing and deploying configuration para obtener mas informacion sobre la configuracion pasos en el menu administrativo administrar  vaya a configuracion   desarrollo   sincronizacion de conf